NP_functionality.VERILOG_PROVIDED:
localparam BITSIZE_OUT = BITSIZE_IN + BANK_ID_SIZE;
`ifdef __M64
localparam OFFSET_BITSIZE = 64;
`else
localparam OFFSET_BITSIZE = 32;
`endif
if_utils #(index, OFFSET_BITSIZE) m_utils();
reg [BITSIZE_OUT-1:0] val;
wire [BITSIZE_OUT-1:0] val_next;

assign val_next = val;

always @(posedge clock) 
begin
  val <= val_next;
  if(setup_port)
  begin
    automatic ptr_t offset = m_utils.read();
    val <= offset[BITSIZE_OUT-1:0];
  end
end

generate 
genvar i;
  for(i = 0; i < CHANNEL_NUMBER; i = i + 1)
  begin
    if(BANK_ID_SIZE == 0)
    begin
      assign Mout_addr_ram_out[i*BITSIZE_OUT +: BITSIZE_OUT] = Mout_addr_ram[BITSIZE_IN +: BITSIZE_IN] + val;
    end
    else
    begin
      assign Mout_addr_ram_out[i*BITSIZE_OUT +: BITSIZE_OUT] = {Mout_addr_ram[(i+1)*BITSIZE_IN-1:i*BITSIZE_IN+EXTERNAL_BANK_ID_LAST_BIT],i[BANK_ID_SIZE-1:0],Mout_addr_ram[i*BITSIZE_IN+EXTERNAL_BANK_ID_LAST_BIT-1:i*BITSIZE_IN]} + val;
    end
  end
endgenerate


if_utils #(index, BITSIZE_m_axi_awaddr) m_utils();
reg [BITSIZE_m_axi_awaddr-1:0] val;
wire [BITSIZE_m_axi_awaddr-1:0] val_next;

assign val_next = val;

always @(posedge clock) 
begin
  val <= val_next;
  if(setup_port)
  begin
    val <= m_utils.read();
  end
end

generate
if(BANK_ID_SIZE == 0)
begin
  assign m_axi_awaddr = m_axi_awaddr_in + val;
  assign m_axi_araddr = m_axi_araddr_in + val;
end
else if(BITSIZE_m_axi_araddr_in == EXTERNAL_BANK_ID_LAST_BIT)
begin
  assign m_axi_awaddr = {ADAPTER_ID[BANK_ID_SIZE-1:0],m_axi_awaddr_in[EXTERNAL_BANK_ID_LAST_BIT-1:0]} + val;
  assign m_axi_araddr = {ADAPTER_ID[BANK_ID_SIZE-1:0],m_axi_araddr_in[EXTERNAL_BANK_ID_LAST_BIT-1:0]} + val;
end
else
begin
  assign m_axi_awaddr = {m_axi_awaddr_in[BITSIZE_m_axi_araddr_in-1:EXTERNAL_BANK_ID_LAST_BIT],ADAPTER_ID[BANK_ID_SIZE-1:0],m_axi_awaddr_in[EXTERNAL_BANK_ID_LAST_BIT-1:0]} + val;
  assign m_axi_araddr = {m_axi_araddr_in[BITSIZE_m_axi_awaddr_in-1:EXTERNAL_BANK_ID_LAST_BIT],ADAPTER_ID[BANK_ID_SIZE-1:0],m_axi_araddr_in[EXTERNAL_BANK_ID_LAST_BIT-1:0]} + val;
end
endgenerate

import "DPI-C" function int m_read (input shortint unsigned id, output logic [4095:0] data, input shortint unsigned bitsize, input ptr_t addr, input byte signed cmd);
import "DPI-C" function int m_write (input shortint unsigned id, input logic [4095:0] data, input shortint unsigned bitsize, input ptr_t addr, input byte signed cmd);
import "DPI-C" function int m_state (input shortint unsigned id, input int data);

function automatic integer log2;
  input integer value;
  `ifdef _SIM_HAVE_CLOG2
    log2 = $clog2(value);
  `else
    automatic integer temp_value = value-1;
    for (log2=0; temp_value > 0; log2=log2+1)
      temp_value = temp_value >> 1;
  `endif
endfunction

localparam BITSIZE_strobe=log2(BITSIZE_data) > 3 ? (1<<(log2(BITSIZE_data)-3)) : 1;

function automatic [BITSIZE_data-1:0] read();
  automatic reg [4095:0] _data = 0;
  void'(m_read(ID, _data, BITSIZE_data, 0, 0));
  return _data[BITSIZE_data-1:0];
endfunction

function automatic [BITSIZE_data-1:0] read_a(input ptr_t addr);
  automatic reg [4095:0] _data = 0;
  void'(m_read(ID, _data, BITSIZE_data, addr, 0));
  return _data[BITSIZE_data-1:0];
endfunction

function automatic [BITSIZE_data-1:0] read_i(output int info);
  automatic reg [4095:0] _data = 0;
  info = m_read(ID, _data, BITSIZE_data, 0, 0);
  return _data[BITSIZE_data-1:0];
endfunction

function automatic [BITSIZE_data-1:0] read_ai(input ptr_t addr, output int info);
  automatic reg [4095:0] _data = 0;
  info = m_read(ID, _data, BITSIZE_data, addr, 0);
  return _data[BITSIZE_data-1:0];
endfunction

function automatic [BITSIZE_data-1:0] pop(output int info);
  automatic reg [4095:0] _data = 0;
  info = m_read(ID, _data, BITSIZE_data, 0, 1);
  return _data[BITSIZE_data-1:0];
endfunction

function automatic int write(input logic [BITSIZE_data-1:0] data);
  automatic reg [4095:0] _data = 0;
  _data[BITSIZE_data-1:0] = data;
  return m_write(ID, _data, BITSIZE_data, 0, 0);
endfunction

function automatic int write_a(input logic [BITSIZE_data-1:0] data, input ptr_t addr);
  automatic reg [4095:0] _data = 0;
  _data[BITSIZE_data-1:0] = data;
  return m_write(ID, _data, BITSIZE_data, addr, 0);
endfunction

function automatic int write_sa(input logic [BITSIZE_data-1:0] data, input shortint unsigned bitsize, input ptr_t addr);
  automatic reg [4095:0] _data = 0;
  _data[BITSIZE_data-1:0] = data;
  return m_write(ID, _data, bitsize, addr, 0);
endfunction

function automatic int write_strobe(input logic [BITSIZE_data-1:0] data, input logic [BITSIZE_strobe-1:0] strobe, input ptr_t addr);
  automatic shortint unsigned size = 0;

  while(strobe != 0 && !strobe[0])
  begin
    addr = addr + 1;
    strobe = strobe >> 1;
  end
  while(strobe[0])
  begin
    size = size + 8;
    strobe = strobe >> 1;
  end
  if(strobe != 0)
  begin
    $display("Scattered strobe write operations not supported");
    $finish;
  end

  return write_sa(data, size, addr);
endfunction

function automatic int push(input logic [BITSIZE_data-1:0] data);
  automatic reg [4095:0] _data = 0;
  _data[BITSIZE_data-1:0] = data;
  return m_write(ID, _data, BITSIZE_data, 0, -1);
endfunction

function automatic int state(input int data);
  return m_state(ID, data);
endfunction

`ifdef VERILATOR
timeunit 1ps;
timeprecision 1ps;
`endif

import "DPI-C" function int unsigned m_next(input int unsigned state);
import "DPI-C" function int m_fini();

localparam [6:0] 
  STATE_READY   =7'b0000001,
  STATE_SETUP   =7'b0000010,
  STATE_RUNNING =7'b0000100,
  STATE_END     =7'b0001000,
  STATE_ERROR   =7'b0010000,
  STATE_ABORT   =7'b0100000,
  SIM_DONE      =7'b1000000;
reg [$bits(STATE_READY)-1:0] state, state_next, state_succ, state_succ_next;

reg rst, rst_next, setup, setup_next, start, start_next;
integer rst_count, rst_count_next;
time over_time;

initial
begin
  // Open file storing the cycles
  automatic integer res_file;
  res_file = $fopen(RESFILE, "w");
  if (res_file == 0)
  begin
    $display("ERROR - Error opening the res_file");
    $finish;// Terminate
  end
  $fwrite(res_file, "");
  $fclose(res_file);

  state = STATE_READY;
  state_next = STATE_READY;
  state_succ = STATE_READY;
  state_succ_next = STATE_READY;
  rst = RESET_ACTIVE;
  rst_next = RESET_ACTIVE;
  rst_count = RESET_CYCLES;
  rst_count_next = RESET_CYCLES;
  setup = 0;
  setup_next = 0;
  start = 0;
  start_next = 0;
  over_time = 0;

  $display("Timing simulation file: %s", RESFILE);
  $display("Reset active: %0s", RESET_ACTIVE ? "HIGH" : "LOW");
end

assign reset = rst;
assign setup_port = setup;
assign start_port = start;

always @(posedge clock)
begin
  state <= state_next;
  state_succ <= state_succ_next;
  rst <= rst_next;
  rst_count <= rst_count_next;
  setup <= setup_next;
  start <= start_next;
  case(state_next)
  STATE_READY:
    begin
      automatic integer unsigned next_state = m_next(STATE_READY);
      `ifndef NDEBUG
      $display("Sim: next state: %0d (retval: %0d)", next_state[$bits(state_succ)-1:0], next_state[15:8]);
      `endif
      state_succ <= next_state[$bits(state_succ)-1:0];
    end
  STATE_SETUP:
    begin
      automatic time start_time = $time + CLOCK_PERIOD;
      automatic time start_cycle = $rtoi($itor(start_time)/CLOCK_PERIOD);
      automatic integer res_file;
      if(setup_next)
      begin
        res_file = $fopen(RESFILE, "a");
        $fwrite(res_file, "%0d|", start_time);
        $fclose(res_file);
        `ifndef NDEBUG
        $display("Sim: Argument setup\nSim: Simulation started at cycle %0d", start_cycle);
        `endif
      end
      over_time <= start_cycle + MAX_SIM_CYCLES;
    end
  STATE_RUNNING:
    begin
      automatic time curr_cycle = $rtoi($itor($time)/CLOCK_PERIOD);
      if(curr_cycle >= over_time)
      begin
        automatic integer res_file;
        res_file = $fopen(RESFILE, "a");
        $fwrite(res_file, "X");
        $fclose(res_file);
        $display("Sim: Simulation exceeds %0d cycles", MAX_SIM_CYCLES);
        $finish;
      end
    end
  SIM_DONE:
    begin
      automatic time curr_time = $time;
      automatic time curr_cycle = $rtoi($itor(curr_time)/CLOCK_PERIOD);
      automatic integer res_file;
      res_file = $fopen(RESFILE, "a");
      $fwrite(res_file, "%0d,", curr_time);
      $fclose(res_file);
      `ifndef NDEBUG
      $display("Sim: DUT port writeback\nSim: Simulation ended at cycle %0d", curr_cycle);
      `endif
    end
  STATE_END:
    begin
      automatic integer r = m_fini();
      automatic integer res_file;
      res_file = $fopen(RESFILE, "a");
      $fwrite(res_file, "\n%0d\n", r[15:8]);
      $fclose(res_file);
      $display("Sim: Driver terminated with code: %0d", r[15:8]);
      $finish;
    end
  STATE_ABORT:
    begin
      automatic integer r = m_fini();
      automatic integer res_file;
      res_file = $fopen(RESFILE, "a");
      $fwrite(res_file, "\nA\n");
      $fclose(res_file);
      $display("Sim: Driver aborted");
      $finish;
    end
  default:
    begin
    end
  endcase
end

always @(*)
begin
  rst_next = rst;
  rst_count_next = rst_count;
  setup_next = setup;
  start_next = start;
  state_next = state;
  state_succ_next = state_succ;
  case(state)
  STATE_READY:
    begin
      state_next = state_succ;
      if(state_succ == STATE_SETUP)
      begin
        if(RESET_ALWAYS || rst_count > 0)
        begin
          rst_next = RESET_ACTIVE;
          rst_count_next = RESET_CYCLES;
        end
        else
        begin
          rst_count_next = 1;
        end
      end
    end
  STATE_SETUP:
    begin
      if(rst_count > 1)
      begin
        setup_next = rst_count == 0;
        rst_next = RESET_ACTIVE;
        rst_count_next = rst_count - 1;
      end
      else if(rst_count == 1)
      begin
        setup_next = 1;
        rst_next = ~RESET_ACTIVE;
        rst_count_next = 0;
      end
      else
      begin
        state_next = STATE_RUNNING;
        setup_next = 0;
        start_next = 1;
      end
    end
  STATE_RUNNING:
    begin
      start_next = 0;
      if(done_port)
      begin
        state_next = SIM_DONE;
      end
    end
  SIM_DONE:
    begin
      // A clock cycle must pass to allow interface modules 
      // finalization operations
      state_next = STATE_READY;
    end
  STATE_END:
    begin
    end
  STATE_ABORT:
    begin
    end
  default:
    begin
      state_next = STATE_READY;
    end
  endcase
end

function automatic integer log2;
  input integer value;
  `ifdef _SIM_HAVE_CLOG2
    log2 = $clog2(value);
  `else
    automatic integer temp_value = value-1;
    for (log2=0; temp_value > 0; log2=log2+1)
      temp_value = temp_value >> 1;
  `endif
endfunction

localparam MEM_DELAY_MAX= MEM_DELAY_READ > MEM_DELAY_WRITE ? MEM_DELAY_READ : MEM_DELAY_WRITE,
  ACTIVE_READ= MEM_DELAY_READ > 1 ? (MEM_DELAY_READ-2) : 0,
  ACTIVE_WRITE= MEM_DELAY_WRITE > 1 ? (MEM_DELAY_WRITE-2) : 0,
  CHANNELS_NUMBER=BITSIZE_Mout_oe_ram,
  BITSIZE_oe=1,
  BITSIZE_we=1,
  BITSIZE_addr=BITSIZE_Mout_addr_ram/CHANNELS_NUMBER,
  BITSIZE_Wsize=BITSIZE_Mout_data_ram_size/CHANNELS_NUMBER,
  BITSIZE_Wdata=BITSIZE_Mout_Wdata_ram/CHANNELS_NUMBER,
  BITSIZE_Rdata=BITSIZE_M_Rdata_ram/CHANNELS_NUMBER,
  BITSIZE_tag=BITSIZE_Mout_tag/CHANNELS_NUMBER,
  BITSIZE_item=BITSIZE_tag+BITSIZE_Wdata+BITSIZE_Wsize+BITSIZE_addr+BITSIZE_we+BITSIZE_oe,
  OFFSET_oe=0,
  OFFSET_we=OFFSET_oe+BITSIZE_oe,
  OFFSET_addr=OFFSET_we+BITSIZE_we,
  OFFSET_Wsize=OFFSET_addr+BITSIZE_addr,
  OFFSET_Wdata=OFFSET_Wsize+BITSIZE_Wsize,
  OFFSET_tag = OFFSET_Wdata+BITSIZE_Wdata,
  BITSIZE_S_Rdata=BITSIZE_Sout_Rdata_ram/BITSIZE_S_oe_ram,
  BITSIZE_S_ready=1,
  SLAVE_VALID=BITSIZE_Mout_oe_ram == BITSIZE_S_oe_ram,
  QUEUE_BITSIZE=QUEUE_SIZE > 1 ? log2(QUEUE_SIZE) : 1;

genvar i;
integer dump_file;
wire [BITSIZE_M_Rdata_ram-1:0] _M_Rdata_ram;

assign S_oe_ram = Mout_oe_ram;
assign S_we_ram = Mout_we_ram;
assign S_addr_ram = Mout_addr_ram;
assign S_data_ram_size = Mout_data_ram_size;
assign S_Wdata_ram = Mout_Wdata_ram;
assign M_Rdata_ram = _M_Rdata_ram;

generate
  if(MEM_DUMP)
  begin
    initial
    begin
      dump_file = $fopen(MEM_DUMP_FILE, "w");
      $fwrite(dump_file, "Channel,Operation,Address,Bitwidth,Data\n");
    end

    always@(posedge clock)
    begin
      if(done_port)
      begin
        $fflush(dump_file);
      end
    end
  end
endgenerate

if_utils #(index, BITSIZE_Rdata) m_utils();

generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin : channel
    wire [BITSIZE_item-1:0] new_elem;
    reg [MEM_DELAY_MAX*BITSIZE_item-1:0] queue;
    wire [MEM_DELAY_MAX*BITSIZE_item-1:0] queue_next;
    wire [BITSIZE_oe-1:0] oe;
    wire [BITSIZE_we-1:0] we;
    ptr_t Waddr, Raddr;
    shortint unsigned Wsize;
    wire [BITSIZE_Wdata-1:0] Wdata;
    reg Wready, Rready;
    reg [BITSIZE_Rdata-1:0] Rdata;

    reg [QUEUE_BITSIZE-1:0] queue_counter;
    wire [QUEUE_BITSIZE-1:0] queue_counter_next;

    assign new_elem = Mout_back_pressure[i] ? {BITSIZE_item{1'b0}} : {Mout_tag[BITSIZE_tag*i+:BITSIZE_tag],Mout_Wdata_ram[BITSIZE_Wdata*i+:BITSIZE_Wdata],Mout_data_ram_size[BITSIZE_Wsize*i+:BITSIZE_Wsize],Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr],Mout_we_ram[BITSIZE_we*i+:BITSIZE_we],Mout_oe_ram[BITSIZE_oe*i+:BITSIZE_oe]};
    assign queue_next = M_back_pressure[i] ? queue[MEM_DELAY_MAX*BITSIZE_item-1:0] : {queue[(MEM_DELAY_MAX-1)*BITSIZE_item-1:0],new_elem};

    always@(posedge clock)
    begin
      if(1RESET_VALUE)
      begin
        queue <= 0;
      end
      else
      begin
        queue <= queue_next;
      end
    end

    assign oe = queue_next[ACTIVE_READ*BITSIZE_item+OFFSET_oe+:BITSIZE_oe];
    assign Raddr = queue_next[ACTIVE_READ*BITSIZE_item+OFFSET_addr+:BITSIZE_addr];
    assign _M_Rdata_ram[BITSIZE_Rdata*i+:BITSIZE_Rdata] = Rdata | (Sout_Rdata_ram[BITSIZE_S_Rdata*i*SLAVE_VALID+:BITSIZE_S_Rdata] & {BITSIZE_S_Rdata{Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1}});

    always@(posedge clock)
    begin : read_channel
      automatic reg [BITSIZE_Rdata-1:0] data;
      Rready <= 0;
      Rdata <= 0;
      if(oe && base_addr <= Raddr)
      begin
        data = m_utils.read_a(Raddr);
        Rdata <= data;
        Rready <= 1;
        if(MEM_DUMP)
        begin
          $fwrite(dump_file, "%0d,r,%0X,%0d,%0X\n", i, Raddr, BITSIZE_Rdata, data);
        end
      end
    end

    assign we = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_we+:BITSIZE_we];
    assign Waddr = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_addr+:BITSIZE_addr];
    assign Wsize = {{16-BITSIZE_Wsize{1'b0}}, queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_Wsize+:BITSIZE_Wsize]};
    assign Wdata = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_Wdata+:BITSIZE_Wdata];

    always@(posedge clock)
    begin : write_channel
      Wready <= 0;
      if(we && base_addr <= Waddr)
      begin
        void'(m_utils.write_sa(Wdata, Wsize, Waddr));
        Wready <= 1;
        if(MEM_DUMP)
        begin
          $fwrite(dump_file, "%0d,w,%0X,%0d,%0X\n", i, Waddr, Wsize, Wdata);
        end
      end
    end

    if(EMULATE_BRAM)
    begin
      assign Mout_back_pressure[i] = 0; // No back pressure with BRAM
    end
    else
    begin
      wire _M_DataRdy, _M_DataRdy_wire;
      assign M_DataRdy[i] = _M_DataRdy;
      assign _M_DataRdy = Wready | Rready | (Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1);
      assign _M_DataRdy_wire = Wready | Rready; // Used to update at posedge clock of the queue_counter;

      always @(posedge clock)
      begin
        if(1RESET_VALUE)
        begin
          queue_counter <= 0;
        end
        else
        begin
          queue_counter <= queue_counter_next;
        end
      end

      if(QUEUE_SIZE > 1)
      begin
        assign queue_counter_next = queue_counter + (((Mout_we_ram[i] || Mout_oe_ram[i]) && !Mout_back_pressure[i] && base_addr <= Mout_addr_ram[i*BITSIZE_addr +: BITSIZE_addr]) && (queue_counter == 0 ? 1 : (queue_counter  - (_M_DataRdy_wire && !M_back_pressure[i])) < (QUEUE_SIZE - 1))) - (_M_DataRdy_wire && !M_back_pressure[i]);
      end
      else 
      begin
        assign queue_counter_next = ((Mout_we_ram[i] || Mout_oe_ram[i]) && !Mout_back_pressure[i] && base_addr <= Mout_addr_ram[i*BITSIZE_addr +: BITSIZE_addr]) || (queue_counter && !_M_DataRdy_wire && !M_back_pressure[i]);
      end

      if(QUEUE_SIZE > 1)
      begin
        assign Mout_back_pressure[i] = M_back_pressure[i] || (queue_counter == 0 ? 0 : (queue_counter - _M_DataRdy_wire) == (QUEUE_SIZE - 1));
      end
      else 
      begin
        assign Mout_back_pressure[i] = M_back_pressure[i] || (queue_counter && !_M_DataRdy_wire);
      end

      reg [BITSIZE_tag-1:0] Rtag, Wtag;
      wire [BITSIZE_tag-1:0] _M_tag;
      assign _M_tag = Wtag | Rtag;
      assign M_tag[BITSIZE_tag*i+:BITSIZE_tag] = _M_tag;

      always@(posedge clock)
      begin 
        Rtag <= 0;
        if(oe && base_addr <= Raddr)
        begin
          Rtag <= queue_next[ACTIVE_READ*BITSIZE_item+OFFSET_tag+:BITSIZE_tag];
        end
      end

      always@(posedge clock)
      begin 
        Wtag <= 0;
        if(we && base_addr <= Waddr)
        begin
          Wtag <= queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_tag+:BITSIZE_tag];
        end
      end
    end

    always @(posedge clock)
    begin
      if (we & oe)
      begin
        $display("ERROR - Mout_we_ram and Mout_oe_ram both enabled on channel %0d!", i);
        $finish;
      end
    end
  end
endgenerate

localparam integer BITSIZE_data = BITSIZE_rdata;
localparam integer BITSIZE_id = BITSIZE_arid;
localparam integer BITSIZE_addr = BITSIZE_araddr;
localparam integer BITSIZE_size = BITSIZE_arsize;
localparam integer BITSIZE_burst = BITSIZE_arburst;
localparam integer BITSIZE_len = BITSIZE_arlen;
localparam integer C_AR = QUEUE_SIZE - 1;
localparam integer C_AW = QUEUE_SIZE - 1;
localparam integer C_W = ((QUEUE_SIZE - 1) > (WRITE_DELAY + 1)) ? (QUEUE_SIZE - 1) : (WRITE_DELAY + 1);
typedef longint unsigned timestamp_t;
if_utils #(index, BITSIZE_data) m_utils();

integer ar_head_reg;
integer ar_tail_reg;
integer ar_count_reg;
integer ar_beat_reg;
reg [BITSIZE_id-1:0] ar_id_reg [0:C_AR-1];
reg [BITSIZE_addr-1:0] ar_addr_reg [0:C_AR-1];
reg [BITSIZE_size-1:0] ar_size_reg [0:C_AR-1];
reg [BITSIZE_burst-1:0] ar_burst_reg [0:C_AR-1];
reg [BITSIZE_len-1:0] ar_len_reg [0:C_AR-1];
reg [BITSIZE_rresp-1:0] ar_resp_reg [0:C_AR-1];
timestamp_t ar_time_reg [0:C_AR-1];
reg next_read_resp_valid;
reg [BITSIZE_rresp-1:0] next_read_resp_value;
integer aw_head_reg;
integer aw_tail_reg;
integer aw_count_reg;
reg [BITSIZE_id-1:0] aw_id_reg [0:C_AW-1];
reg [BITSIZE_addr-1:0] aw_addr_reg [0:C_AW-1];
reg [BITSIZE_size-1:0] aw_size_reg [0:C_AW-1];
reg [BITSIZE_burst-1:0] aw_burst_reg [0:C_AW-1];
reg [BITSIZE_len-1:0] aw_len_reg [0:C_AW-1];
reg [BITSIZE_bresp-1:0] aw_resp_reg [0:C_AW-1];
timestamp_t aw_time_reg [0:C_AW-1];
reg next_write_resp_valid;
reg [BITSIZE_bresp-1:0] next_write_resp_value;
integer aw_committed_reg [0:C_AW-1];
reg aw_complete_reg [0:C_AW-1];
integer w_head_reg;
integer w_tail_reg;
integer w_count_reg;
reg [BITSIZE_data-1:0] w_data_reg [0:C_W-1];
reg [BITSIZE_wstrb-1:0] w_strb_reg [0:C_W-1];
reg w_last_reg [0:C_W-1];
timestamp_t w_time_reg [0:C_W-1];
timestamp_t cycle_count_reg;
reg rvalid_reg;
reg rlast_reg;
reg [BITSIZE_id-1:0] rid_reg;
reg [BITSIZE_data-1:0] rdata_reg;
reg [BITSIZE_rresp-1:0] rresp_reg;
reg [BITSIZE_ruser-1:0] ruser_reg;

task automatic inject_next_read_response(input [BITSIZE_rresp-1:0] response);
begin
  if (next_read_resp_valid)
    $fatal(1, "AXI read response override is already pending");
  next_read_resp_value = response;
  next_read_resp_valid = 1'b1;
end
endtask

task automatic inject_next_write_response(input [BITSIZE_bresp-1:0] response);
begin
  if (next_write_resp_valid)
    $fatal(1, "AXI write response override is already pending");
  next_write_resp_value = response;
  next_write_resp_valid = 1'b1;
end
endtask

assign arready = ar_count_reg < C_AR;
assign awready = aw_count_reg < C_AW;
assign wready = w_count_reg < C_W;
assign rvalid = rvalid_reg;
assign rlast = rlast_reg;
assign rid = rid_reg;
assign rdata = rdata_reg;
assign rresp = rresp_reg;
assign ruser = ruser_reg;
assign bvalid = aw_count_reg > 0 && aw_complete_reg[aw_head_reg];
assign bid = bvalid ? aw_id_reg[aw_head_reg] : '0;
assign bresp = bvalid ? aw_resp_reg[aw_head_reg] : '0;
assign buser = '0;

wire ar_push = arvalid && arready;
wire aw_push = awvalid && awready;
wire w_push = wvalid && wready;
wire b_pop = bvalid && bready;
wire r_pop = rvalid_reg && rready;
wire ar_pop = r_pop && rlast_reg;
wire [31:0] read_slot = ar_pop ? (ar_head_reg + 1) % C_AR : ar_head_reg;
wire [31:0] read_beat = r_pop ? (rlast_reg ? 0 : ar_beat_reg + 1) : ar_beat_reg;
wire read_load = (!rvalid_reg || rready) && (ar_count_reg > (ar_pop ? 1 : 0)) &&
    cycle_count_reg >= ar_time_reg[read_slot] + READ_DELAY - 1;
wire [BITSIZE_addr-1:0] read_address = ar_burst_reg[read_slot] == 2'b00 ?
    ar_addr_reg[read_slot] : ar_addr_reg[read_slot] + read_beat * (1 << ar_size_reg[read_slot]);

// AXI4 write data has no ID. Associate it with the oldest incomplete AW,
// including an AW accepted on this edge when there is no older owner.
integer queued_owner;
always @(*)
begin : find_write_owner
  integer scan_i;
  integer scan_slot;
  queued_owner = -1;
  scan_slot = 0;
  for (scan_i = 0; scan_i < aw_count_reg; scan_i = scan_i + 1)
  begin
    scan_slot = (aw_head_reg + scan_i) % C_AW;
    if (queued_owner == -1 && !aw_complete_reg[scan_slot])
      queued_owner = scan_slot;
  end
end

wire aw_is_new = queued_owner == -1 && aw_push;
wire w_is_new = w_count_reg == 0 && w_push;
wire [31:0] write_owner = aw_is_new ? aw_tail_reg : queued_owner;
wire [BITSIZE_addr-1:0] write_base = aw_is_new ? awaddr : aw_addr_reg[write_owner];
wire [BITSIZE_size-1:0] write_size = aw_is_new ? awsize : aw_size_reg[write_owner];
wire [BITSIZE_burst-1:0] write_burst = aw_is_new ? awburst : aw_burst_reg[write_owner];
wire [BITSIZE_len-1:0] write_length = aw_is_new ? awlen : aw_len_reg[write_owner];
wire [BITSIZE_data-1:0] write_data = w_is_new ? wdata : w_data_reg[w_head_reg];
wire [BITSIZE_wstrb-1:0] write_strobe = w_is_new ? wstrb : w_strb_reg[w_head_reg];
wire write_last = w_is_new ? wlast : w_last_reg[w_head_reg];
wire [63:0] write_aw_time = aw_is_new ? cycle_count_reg : aw_time_reg[write_owner];
wire [63:0] write_w_time = w_is_new ? cycle_count_reg : w_time_reg[w_head_reg];
wire [63:0] write_eligible_at =
    (write_aw_time > write_w_time ? write_aw_time : write_w_time) + WRITE_DELAY - 1;
wire commit_write = (queued_owner != -1 || aw_is_new) && (w_count_reg > 0 || w_is_new) &&
    cycle_count_reg >= write_eligible_at;
wire [31:0] write_beat = aw_is_new ? 0 : aw_committed_reg[write_owner];
wire [31:0] write_beats = {1'b0, write_length} + 1;
wire write_final = write_beat == write_beats - 1;
wire [BITSIZE_addr-1:0] write_address = write_burst == 2'b00 ?
    write_base : write_base + write_beat * (1 << write_size);
wire w_enqueue = w_push && !(commit_write && w_is_new);
wire w_pop = commit_write && !w_is_new;

always @(posedge clock)
begin
  if (1RESET_VALUE)
    cycle_count_reg <= 0;
  else
  begin
    cycle_count_reg <= cycle_count_reg + 1;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    ar_head_reg <= 0;
  else
  begin
    if (ar_pop)
      ar_head_reg <= (ar_head_reg + 1) % C_AR;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    ar_tail_reg <= 0;
  else
  begin
    if (ar_push)
      ar_tail_reg <= (ar_tail_reg + 1) % C_AR;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    ar_count_reg <= 0;
  else
  begin
    case ({ar_push, ar_pop})
      2'b10: ar_count_reg <= ar_count_reg + 1;
      2'b01: ar_count_reg <= ar_count_reg - 1;
      default: ar_count_reg <= ar_count_reg;
    endcase
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    ar_beat_reg <= 0;
  else
  begin
    if (r_pop)
      ar_beat_reg <= rlast_reg ? 0 : ar_beat_reg + 1;
  end
end

always @(posedge clock)
begin : update_ar_id
  if (!(1RESET_VALUE))
  begin
    if (ar_push)
      ar_id_reg[ar_tail_reg] <= arid;
  end
end

always @(posedge clock)
begin : update_ar_addr
  if (!(1RESET_VALUE))
  begin
    if (ar_push)
      ar_addr_reg[ar_tail_reg] <= araddr;
  end
end

always @(posedge clock)
begin : update_ar_size
  if (!(1RESET_VALUE))
  begin
    if (ar_push)
      ar_size_reg[ar_tail_reg] <= arsize;
  end
end

always @(posedge clock)
begin : update_ar_burst
  if (!(1RESET_VALUE))
  begin
    if (ar_push)
      ar_burst_reg[ar_tail_reg] <= arburst;
  end
end

always @(posedge clock)
begin : update_ar_len
  if (!(1RESET_VALUE))
  begin
    if (ar_push)
      ar_len_reg[ar_tail_reg] <= arlen;
  end
end

always @(posedge clock)
begin : update_ar_resp
  integer ar_resp_i;
  if (1RESET_VALUE)
  begin
    next_read_resp_valid <= 1'b0;
    next_read_resp_value <= '0;
    for (ar_resp_i = 0; ar_resp_i < C_AR; ar_resp_i = ar_resp_i + 1)
      ar_resp_reg[ar_resp_i] <= '0;
  end
  else if (ar_push)
  begin
    ar_resp_reg[ar_tail_reg] <= next_read_resp_valid ? next_read_resp_value : '0;
    if (next_read_resp_valid)
      next_read_resp_valid <= 1'b0;
  end
end

always @(posedge clock)
begin : update_ar_time
  integer ar_time_i;
  if (1RESET_VALUE)
  begin
    for (ar_time_i = 0; ar_time_i < C_AR; ar_time_i = ar_time_i + 1)
      ar_time_reg[ar_time_i] <= 0;
  end
  else
  begin
    if (ar_push)
      ar_time_reg[ar_tail_reg] <= cycle_count_reg;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    rvalid_reg <= 0;
  else
  begin
    if (!rvalid_reg || rready)
      rvalid_reg <= read_load;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    rid_reg <= '0;
  else
  begin
    if (read_load)
      rid_reg <= ar_id_reg[read_slot];
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    rlast_reg <= '0;
  else
  begin
    if (read_load)
      rlast_reg <= read_beat == ar_len_reg[read_slot];
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    rresp_reg <= '0;
  else
  begin
    if (read_load)
      rresp_reg <= ar_resp_reg[read_slot];
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    ruser_reg <= '0;
  else
  begin
    if (read_load)
      ruser_reg <= '0;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    aw_head_reg <= 0;
  else
  begin
    if (b_pop)
      aw_head_reg <= (aw_head_reg + 1) % C_AW;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    aw_tail_reg <= 0;
  else
  begin
    if (aw_push)
      aw_tail_reg <= (aw_tail_reg + 1) % C_AW;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    aw_count_reg <= 0;
  else
  begin
    case ({aw_push, b_pop})
      2'b10: aw_count_reg <= aw_count_reg + 1;
      2'b01: aw_count_reg <= aw_count_reg - 1;
      default: aw_count_reg <= aw_count_reg;
    endcase
  end
end

always @(posedge clock)
begin : update_aw_id
  if (!(1RESET_VALUE))
  begin
    if (aw_push)
      aw_id_reg[aw_tail_reg] <= awid;
  end
end

always @(posedge clock)
begin : update_aw_addr
  if (!(1RESET_VALUE))
  begin
    if (aw_push)
      aw_addr_reg[aw_tail_reg] <= awaddr;
  end
end

always @(posedge clock)
begin : update_aw_size
  if (!(1RESET_VALUE))
  begin
    if (aw_push)
      aw_size_reg[aw_tail_reg] <= awsize;
  end
end

always @(posedge clock)
begin : update_aw_burst
  if (!(1RESET_VALUE))
  begin
    if (aw_push)
      aw_burst_reg[aw_tail_reg] <= awburst;
  end
end

always @(posedge clock)
begin : update_aw_len
  if (!(1RESET_VALUE))
  begin
    if (aw_push)
      aw_len_reg[aw_tail_reg] <= awlen;
  end
end

always @(posedge clock)
begin : update_aw_resp
  integer aw_resp_i;
  if (1RESET_VALUE)
  begin
    next_write_resp_valid <= 1'b0;
    next_write_resp_value <= '0;
    for (aw_resp_i = 0; aw_resp_i < C_AW; aw_resp_i = aw_resp_i + 1)
      aw_resp_reg[aw_resp_i] <= '0;
  end
  else if (aw_push)
  begin
    aw_resp_reg[aw_tail_reg] <= next_write_resp_valid ? next_write_resp_value : '0;
    if (next_write_resp_valid)
      next_write_resp_valid <= 1'b0;
  end
end

always @(posedge clock)
begin : update_aw_time
  integer aw_time_i;
  if (1RESET_VALUE)
  begin
    for (aw_time_i = 0; aw_time_i < C_AW; aw_time_i = aw_time_i + 1)
      aw_time_reg[aw_time_i] <= 0;
  end
  else
  begin
    if (aw_push)
      aw_time_reg[aw_tail_reg] <= cycle_count_reg;
  end
end

always @(posedge clock)
begin : update_aw_committed
  integer aw_committed_i;
  if (1RESET_VALUE)
  begin
    for (aw_committed_i = 0; aw_committed_i < C_AW; aw_committed_i = aw_committed_i + 1)
      aw_committed_reg[aw_committed_i] <= 0;
  end
  else
  begin
    if (b_pop)
      aw_committed_reg[aw_head_reg] <= 0;
    if (aw_push)
      aw_committed_reg[aw_tail_reg] <= (commit_write && aw_is_new) ? write_beat + 1 : 0;
    if (commit_write && !aw_is_new)
      aw_committed_reg[write_owner] <= write_beat + 1;
  end
end

always @(posedge clock)
begin : update_aw_complete
  integer aw_complete_i;
  if (1RESET_VALUE)
  begin
    for (aw_complete_i = 0; aw_complete_i < C_AW; aw_complete_i = aw_complete_i + 1)
      aw_complete_reg[aw_complete_i] <= 0;
  end
  else
  begin
    if (b_pop)
      aw_complete_reg[aw_head_reg] <= 0;
    if (aw_push)
      aw_complete_reg[aw_tail_reg] <= commit_write && aw_is_new && write_final;
    if (commit_write && !aw_is_new && write_final)
      aw_complete_reg[write_owner] <= 1;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    w_head_reg <= 0;
  else
  begin
    if (w_pop)
      w_head_reg <= (w_head_reg + 1) % C_W;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    w_tail_reg <= 0;
  else
  begin
    if (w_enqueue)
      w_tail_reg <= (w_tail_reg + 1) % C_W;
  end
end

always @(posedge clock)
begin
  if (1RESET_VALUE)
    w_count_reg <= 0;
  else
  begin
    case ({w_enqueue, w_pop})
      2'b10: w_count_reg <= w_count_reg + 1;
      2'b01: w_count_reg <= w_count_reg - 1;
      default: w_count_reg <= w_count_reg;
    endcase
  end
end

always @(posedge clock)
begin : update_w_data_q
  if (!(1RESET_VALUE))
  begin
    if (w_enqueue)
      w_data_reg[w_tail_reg] <= wdata;
  end
end

always @(posedge clock)
begin : update_w_strb_q
  if (!(1RESET_VALUE))
  begin
    if (w_enqueue)
      w_strb_reg[w_tail_reg] <= wstrb;
  end
end

always @(posedge clock)
begin : update_w_last_q
  if (!(1RESET_VALUE))
  begin
    if (w_enqueue)
      w_last_reg[w_tail_reg] <= wlast;
  end
end

always @(posedge clock)
begin : update_w_time_q
  integer w_time_q_i;
  if (1RESET_VALUE)
  begin
    for (w_time_q_i = 0; w_time_q_i < C_W; w_time_q_i = w_time_q_i + 1)
      w_time_reg[w_time_q_i] <= 0;
  end
  else
  begin
    if (w_enqueue)
      w_time_reg[w_tail_reg] <= cycle_count_reg;
  end
end

// Keep backend calls together and in read-before-write order. This preserves
// the value seen by a read aliasing a write committed on the same edge.
always @(posedge clock)
begin : independent_axi_model
  if (1RESET_VALUE)
    rdata_reg <= '0;
  else
  begin
    if (read_load)
    begin
      case (ar_burst_reg[read_slot])
        2'b00, 2'b01: rdata_reg <= m_utils.read_a(read_address);
        default: $fatal(1, "Unsupported AXI read burst type: %0d", ar_burst_reg[read_slot]);
      endcase
    end
    if (commit_write)
    begin
      if (write_last != write_final)
        $fatal(1, "AXI WLAST mismatch at beat %0d of %0d", write_beat, write_beats);
      case (write_burst)
        2'b00, 2'b01: void'(m_utils.write_strobe(write_data, write_strobe, write_address));
        default: $fatal(1, "Unsupported AXI write burst type: %0d", write_burst);
      endcase
    end
  end
end

localparam MEM_DELAY_MAX= MEM_DELAY_READ > MEM_DELAY_WRITE ? MEM_DELAY_READ : MEM_DELAY_WRITE,
  BITSIZE_item=BITSIZE_dat_im+1+1;
reg cyc, stb, we, stall, ack;
reg [BITSIZE_addr_om-1:0] addr;
reg [BITSIZE_dat_om-1:0] Wdata;
reg [7:0] size;
reg [BITSIZE_dat_im-1:0] Rdata;

reg [MEM_DELAY_MAX*BITSIZE_item-1:0] queue, queue_next;

if_utils #(index, BITSIZE_dat_im) m_utils();

initial
begin
  stall = 0;
  ack = 0;
  Rdata = 0;
  queue = 0;
end

assign cyc_is = 0;
assign stb_is = 0;
assign addr_is = 0;
assign dat_is = 0;
assign sel_is = 0;

assign cyc = cyc_om;
assign stb = stb_om;
assign we = we_om;
assign addr = addr_om;
assign Wdata = dat_om;
assign size = sel_om;
assign stall_im = stall; // & cyc
assign ack_im = ack; // & cyc
assign dat_im = Rdata; // & {BITSIZE_dat_im{cyc}};

always @(posedge clock)
begin
  automatic reg w_ack = queue_next[(MEM_DELAY_WRITE-1)*BITSIZE_item] & queue_next[(MEM_DELAY_WRITE-1)*BITSIZE_item+1];
  automatic reg r_ack = queue_next[(MEM_DELAY_READ-1)*BITSIZE_item] & ~queue_next[(MEM_DELAY_READ-1)*BITSIZE_item+1];
  ack <= w_ack | r_ack;
  Rdata <= queue_next[(MEM_DELAY_READ-1)*BITSIZE_item+2 +:BITSIZE_dat_im];
  queue <= queue_next;
end

always @(*)
begin
  queue_next = {queue[(MEM_DELAY_MAX-1)*BITSIZE_item-1:0], {BITSIZE_dat_im{1'b0}}, 1'b0, 1'b0};
  if(cyc & stb)
  begin
    queue_next[1:0] = {we, 1'b1};
  end
end

always @(negedge clock)
begin
  if(queue_next[0])
  begin
    automatic ptr_t ptr_addr = addr;
    if(queue_next[1])
    begin
      void'(m_utils.write_strobe(Wdata, sel_om, ptr_addr));
    end
    else
    begin
      queue_next[BITSIZE_item-1:2] <= m_utils.read_a(ptr_addr);
    end
  end
end

if_utils #(index, BITSIZE_val_port) m_utils();
reg [BITSIZE_val_port-1:0] val;
wire [BITSIZE_val_port-1:0] val_next;

initial val = 0;

assign val_port = val;
assign val_next = val;

always @(posedge clock) 
begin
  val <= val_next;
  if(setup_port)
  begin
    val <= m_utils.read();
  end
end

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
  CHANNELS_NUMBER=BITSIZE_S_we_ram,
  BITSIZE_we=1,
  BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
  BITSIZE_Wsize=BITSIZE_S_data_ram_size/CHANNELS_NUMBER,
  BITSIZE_Wdata=BITSIZE_S_Wdata_ram/CHANNELS_NUMBER,
  BITSIZE_ready=1;
reg [bitsize-1:0] val, val_next;
reg we, we_next, waiting, waiting_next, start, start_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
reg [BITSIZE_Wdata-1:0] data, data_next;
reg [BITSIZE_Wsize-1:0] data_size, data_size_next;
wire rdy;

if_utils #(index, bitsize) m_utils();

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {BITSIZE_S_oe_ram{1'b0}};
assign S_we_ram = {{BITSIZE_S_we_ram-BITSIZE_we{1'b0}}, we_next};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {{BITSIZE_S_Wdata_ram-BITSIZE_Wdata{1'b0}}, data_next};
assign S_data_ram_size = {{BITSIZE_S_data_ram_size-BITSIZE_Wsize{1'b0}}, data_size_next};
assign start_port = start;

always @(posedge clock) 
begin
  val <= val_next;
  we <= we_next;
  addr <= addr_next;
  data <= data_next;
  data_size <= data_size_next;
  waiting <= waiting_next;
  start <= start_next;
  if(1RESET_VALUE)
  begin
    val <= 0;
    we <= 0;
    addr <= 0;
    data <= 0;
    data_size <= 0;
    waiting <= 0;
    start <= 0;
  end
  else if(setup_port)
  begin
    val <= m_utils.read();
  end
end

always @(*)
begin
  val_next = val;
  we_next = we & HOLD & waiting & ~rdy;
  addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
  data_next = data & {BITSIZE_Wdata{HOLD & waiting & ~rdy}};
  data_size_next = data_size & {BITSIZE_Wsize{HOLD & waiting & ~rdy}};
  waiting_next = waiting & ~rdy;
  start_next = waiting & rdy;
  if(i_start_port)
  begin
    we_next = 1;
    addr_next = tgt_addr;
    data_next = {{BITSIZE_Wdata-bitsize{1'b0}}, val};
    data_size_next = bitsize;
    waiting_next = ~rdy;
    start_next = rdy;
  end
end

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
  CHANNELS_NUMBER=BITSIZE_S_oe_ram,
  BITSIZE_oe=1,
  BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
  BITSIZE_ready=1,
  BITSIZE_Rdata=BITSIZE_Sout_Rdata_ram/CHANNELS_NUMBER;
reg oe, oe_next, waiting, waiting_next, done, done_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
wire rdy;

if_utils #(index, bitsize) m_utils();

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {{BITSIZE_S_oe_ram-BITSIZE_oe{1'b0}}, oe_next};
assign S_we_ram = {BITSIZE_S_we_ram{1'b0}};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {BITSIZE_S_Wdata_ram{1'b0}};
assign S_data_ram_size = {BITSIZE_S_data_ram_size{1'b0}};
assign start_port = i_start_port;
assign done_port = done;

always @(posedge clock) 
begin
  oe <= oe_next;
  addr <= addr_next;
  waiting <= waiting_next;
  done <= done_next;
  if(1RESET_VALUE)
  begin
    oe <= 0;
    addr <= 0;
    waiting <= 0;
    done <= 0;
  end
  else if(done_next)
  begin
    void'(m_utils.write(Sout_Rdata_ram[BITSIZE_Rdata-1:0]));
  end
end

always @(*)
begin
  oe_next = oe & HOLD & waiting & ~rdy;
  addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
  waiting_next = waiting & ~rdy;
  done_next = waiting & rdy;
  if(i_done_port)
  begin
    oe_next = 1;
    addr_next = tgt_addr;
    waiting_next = ~rdy;
    done_next = rdy;
  end
end

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
  CHANNELS_NUMBER=BITSIZE_S_we_ram,
  BITSIZE_we=1,
  BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
  BITSIZE_Wsize=BITSIZE_S_data_ram_size/CHANNELS_NUMBER,
  BITSIZE_Wdata=BITSIZE_S_Wdata_ram/CHANNELS_NUMBER,
  BITSIZE_ready=1;
reg we, we_next, waiting, waiting_next, start, start_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
reg [BITSIZE_Wdata-1:0] data, data_next;
reg [BITSIZE_Wsize-1:0] data_size, data_size_next;
wire rdy;

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {BITSIZE_S_oe_ram{1'b0}};
assign S_we_ram = {{BITSIZE_S_we_ram-BITSIZE_we{1'b0}}, we_next};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {{BITSIZE_S_Wdata_ram-BITSIZE_Wdata{1'b0}}, data_next};
assign S_data_ram_size = {{BITSIZE_S_data_ram_size-BITSIZE_Wsize{1'b0}}, data_size_next};
assign start_port = start;

always @(posedge clock) 
begin
  we <= we_next;
  addr <= addr_next;
  data <= data_next;
  data_size <= data_size_next;
  waiting <= waiting_next;
  start <= start_next;
  if(1RESET_VALUE)
  begin
    we <= 0;
    addr <= 0;
    data <= 0;
    data_size <= 0;
    waiting <= 0;
    start <= 0;
  end
end

always @(*)
begin
  we_next = we & HOLD & waiting & ~rdy;
  addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
  data_next = data & {BITSIZE_Wdata{HOLD & waiting & ~rdy}};
  data_size_next = data_size & {BITSIZE_Wsize{HOLD & waiting & ~rdy}};
  waiting_next = waiting & ~rdy;
  start_next = waiting & rdy;
  if(i_start_port)
  begin
    we_next = 1;
    addr_next = tgt_addr;
    data_next = 1;
    data_size_next = 1;
    waiting_next = ~rdy;
    start_next = rdy;
  end
end

localparam bytesize=((bitsize>>3)<<3) == bitsize ? (bitsize>>3) : ((bitsize>>3) + 1);
reg [bitsize-1:0] val;
wire [bitsize-1:0] val_next;
reg cyc, cyc_next, stb, stb_next, we, we_next, stall, ack, start;
reg [BITSIZE_addr_is-1:0] addr, addr_next;
reg [BITSIZE_dat_is-1:0] data, data_next;
reg [BITSIZE_sel_is-1:0] sel, sel_next;

if_utils #(index, bitsize) m_utils();

initial
begin
  val = 0;
  cyc = 0;
  cyc_next = 0;
  stb = 0;
  stb_next = 0;
  we = 0;
  we_next = 0;
  addr = 0;
  addr_next = 0;
  data = 0;
  data_next = 0;
  sel = 0;
  sel_next = 0;
  start = 0;
end

assign cyc_is = cyc_next;
assign stb_is = stb_next;
assign we_is = we_next;
assign addr_is = addr_next;
assign dat_is = data_next;
assign sel_is = sel_next;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = start;

always @(posedge clock) 
begin
  automatic reg active_tx = cyc_next & ~ack;
  automatic reg wait_tx = active_tx & stall;
  val <= val_next;
  cyc <= active_tx;
  stb <= stb_next & wait_tx;
  we <= we_next & wait_tx;
  addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
  data <= data_next & {BITSIZE_dat_is{wait_tx}};
  sel <= sel_next & {BITSIZE_sel_is{wait_tx}};
  start <= ack & cyc_next;
  if(setup_port)
  begin
    val <= m_utils.read();
  end
end

assign val_next = val;

always @(*)
begin
  cyc_next = cyc;
  stb_next = stb;
  we_next = we;
  addr_next = addr;
  data_next = data;
  sel_next = sel;
  if(i_start_port)
  begin
    cyc_next = 1;
    stb_next = 1;
    we_next = 1;
    addr_next = tgt_addr;
    data_next[bitsize-1:0] = val;
    sel_next = {bytesize{1'b1}};
  end
end

localparam bytesize=((bitsize>>3)<<3) == bitsize ? (bitsize>>3) : ((bitsize>>3) + 1);
reg cyc, cyc_next, stb, stb_next, stall, ack, done;
reg [BITSIZE_addr_is-1:0] addr, addr_next;

if_utils #(index, bitsize) m_utils();

initial
begin
  cyc = 0;
  cyc_next = 0;
  stb = 0;
  stb_next = 0;
  addr = 0;
  addr_next = 0;
  done = 0;
end

assign cyc_is = cyc_next;
assign stb_is = stb_next;
assign we_is = 0;
assign addr_is = addr_next;
assign dat_is = 0;
assign sel_is = 0;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = i_start_port;
assign done_port = done;

always @(posedge clock) 
begin
  automatic reg active_tx = cyc_next & ~ack;
  automatic reg wait_tx = active_tx & stall;
  cyc <= active_tx;
  stb <= stb_next & wait_tx;
  addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
  done <= ack & cyc_next;
  if(ack & cyc_next)
  begin
    void'(m_utils.write(dat_os));
  end
end

always @(*)
begin
  cyc_next = cyc;
  stb_next = stb;
  addr_next = addr;
  if(i_done_port)
  begin
    cyc_next = 1;
    stb_next = 1;
    addr_next = tgt_addr;
  end
end

localparam bytesize=1;
reg cyc, cyc_next, stb, stb_next, we, we_next, stall, ack, start;
reg [BITSIZE_addr_is-1:0] addr, addr_next;
reg [BITSIZE_dat_is-1:0] data, data_next;
reg [BITSIZE_sel_is-1:0] sel, sel_next;

initial
begin
  cyc = 0;
  cyc_next = 0;
  stb = 0;
  stb_next = 0;
  we = 0;
  we_next = 0;
  addr = 0;
  addr_next = 0;
  data = 0;
  data_next = 0;
  sel = 0;
  sel_next = 0;
  start = 0;
end

assign cyc_is = cyc_next;
assign stb_is = stb_next;
assign we_is = we_next;
assign addr_is = addr_next;
assign dat_is = data_next;
assign sel_is = sel_next;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = start;

always @(posedge clock) 
begin
  automatic reg active_tx = cyc_next & ~ack;
  automatic reg wait_tx = active_tx & stall;
  cyc <= active_tx;
  stb <= stb_next & wait_tx;
  we <= we_next & wait_tx;
  addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
  data <= data_next & {BITSIZE_dat_is{wait_tx}};
  sel <= sel_next & {BITSIZE_sel_is{wait_tx}};
