if_utils #(index, BITSIZE_val_port) m_utils();
always @(posedge clock)
begin
  if(done_port)
  begin
    void'(m_utils.write(val_port));
  end
end

localparam CHANNELS_NUMBER=PORTSIZE_ce,
  BITSIZE_dq=BITSIZE_d > BITSIZE_q ? BITSIZE_d : BITSIZE_q,
  BITSIZE_item=BITSIZE_d+BITSIZE_address+BITSIZE_ce+BITSIZE_we,
  BITSIZE_chunk=BITSIZE_item*CHANNELS_NUMBER,
  OFFSET_ce=0,
  OFFSET_we=OFFSET_ce+BITSIZE_ce,
  OFFSET_address=OFFSET_we+BITSIZE_we,
  OFFSET_data=OFFSET_address+BITSIZE_address,
  LAST_READ_item=READ_DELAY > 1 ? READ_DELAY-2 : 0,
  LAST_READ_size=READ_DELAY > 1 ? READ_DELAY-1 : 1;
genvar i;

if_utils #(index, BITSIZE_dq) m_utils();

wire [BITSIZE_chunk-1:0] current;
reg [BITSIZE_chunk*WRITE_DELAY-1:0] queue = 0, queue_next = 0;
reg [CHANNELS_NUMBER*BITSIZE_q*LAST_READ_size-1:0] _q_next = 0;
reg [CHANNELS_NUMBER*BITSIZE_q*LAST_READ_size-1:0] _q = 0;

generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin
    assign current[BITSIZE_item*i+:BITSIZE_item] = {d[BITSIZE_d*i+:BITSIZE_d], address[BITSIZE_address*i+:BITSIZE_address], we[BITSIZE_we*i+:BITSIZE_we], ce[BITSIZE_ce*i+:BITSIZE_ce]};
    assign q[BITSIZE_q*i+:BITSIZE_q] = _q[LAST_READ_item*BITSIZE_q*CHANNELS_NUMBER+BITSIZE_q*i+:BITSIZE_q];
  end
endgenerate

generate
  if(WRITE_DELAY > 1)
  begin
    always @(posedge clock)
    begin
      if(setup_port)
      begin
        queue[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] <= 0;
        queue[BITSIZE_chunk-1:0] <= current;
      end
      else
      begin
        queue[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] <= queue_next[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk];
        queue[BITSIZE_chunk-1:0] <= current;
      end
    end
    always @(*)
    begin
      queue_next[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] = queue[BITSIZE_chunk*(WRITE_DELAY-1)-1:0];
      queue_next[BITSIZE_chunk-1:0] = 0;
    end
  end
endgenerate

generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin : write_port
    if(WRITE_DELAY > 1)
    begin
      always @(posedge clock)
      begin
        automatic ptr_t address = queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
        automatic reg [BITSIZE_d-1:0] data = queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_data+:BITSIZE_d];
        if(queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1
          && queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b1)
        begin
          void'(m_utils.write_a(data, address));
        end
      end
    end
    else
    begin
      always @(posedge clock)
      begin
        automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
        automatic reg [BITSIZE_d-1:0] data = current[BITSIZE_item*i+OFFSET_data+BITSIZE_d-1:BITSIZE_item*i+OFFSET_data];
        if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1 && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b1)
        begin
          void'(m_utils.write_a(data, address));
        end
      end
    end
  end
endgenerate

generate
  if(READ_DELAY > 2)
  begin : shift_output_queue1
    always @(*)
    begin
      _q_next[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER] = _q[LAST_READ_item*CHANNELS_NUMBER*BITSIZE_q-1:0];
    end
  end
endgenerate
generate
  if(READ_DELAY > 2)
  begin : shift_output_queue2
    always @(posedge clock)
    begin
      _q[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER] <= _q_next[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER];
    end
  end
endgenerate
generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin : read_port
    if(READ_DELAY > 1)
    begin
      always @(posedge clock)
      begin
        if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1
            && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b0)
        begin
          automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
          _q[BITSIZE_q*i+:BITSIZE_q] <= m_utils.read_a(address);
        end
      end
    end
    else
    begin
      always @(*)
      begin
        if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1 && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b0)
        begin
          automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
          _q[BITSIZE_q*i+:BITSIZE_q] = m_utils.read_a(address);
        end
      end
    end
  end
endgenerate

if_utils #(index, BITSIZE_dout) m_utils();

reg enable, enable_next;
reg _empty_n, _empty_n_next;
reg [BITSIZE_dout-1:0] val, val_next;

initial
begin
  enable = 0;
  _empty_n = 0;
  val = 0;
end

assign dout = val;
assign empty_n = _empty_n;

always @(posedge clock)
begin
  enable <= enable_next;
  _empty_n <= _empty_n_next;
  val <= val_next;
  if(setup_port)
  begin
    automatic int data = 0;
    val <= m_utils.read_i(data);
    _empty_n <= data > 0;
    enable <= 1'b1;
  end
  else if((enable_next | done_port) & read)
  begin
    automatic int data = 0;
    if(~_empty_n_next)
    begin
      $display("Too many read requests on interface %0d", index);
      $finish;
    end
    val <= m_utils.pop(data);
    _empty_n <= data > 0;
  end
end

always @(*)
begin
  enable_next = enable & ~done_port;
  _empty_n_next = _empty_n;
  val_next = val;
end

generate
  if(CHECK_ACK)
  begin
    reg ack_check, ack_check_next;
    initial ack_check = 0;
    assign ack_check_next = read | ack_check;
    always @(posedge clock)
    begin
      ack_check <= ack_check_next;
      if(setup_port)
      begin
        ack_check <= 0;
      end
      if(done_port & ~ack_check_next)
      begin
        $display("WARNING: Acknowledge signal never asserted on interface %0d.", index);
      end
    end
  end
endgenerate

if_utils #(index, BITSIZE_din) m_utils();

reg enable, enable_next;
reg _full_n, _full_n_next;

initial
begin
  enable = 0;
  _full_n = 0;
end

assign full_n = _full_n;

always @(posedge clock)
begin
  enable <= enable_next;
  _full_n <= _full_n_next;
  if(setup_port)
  begin
    automatic int data = 0;
    data = m_utils.state(4);
    _full_n <= data > 0;
    enable <= 1'b1;
  end
  if((enable_next | done_port) & write)
  begin
    automatic int data = 0;
    data = m_utils.push(din);
    _full_n <= data > 0;
    if(data < 0)
    begin
      $display("Too many write requests on interface %0d", index);
      $finish;
    end
  end
end

always @(*) 
begin
  enable_next = enable & ~done_port;
  _full_n_next = _full_n;
end

import "DPI-C" function int m_read_request (input byte unsigned id, input shortint unsigned bitsize, input ptr_t addr, input byte cmd);
import "DPI-C" function int m_read_complete (input byte unsigned id, output logic [4095:0] data);
import "DPI-C" function int m_read_complete_ch (input byte unsigned id, input byte unsigned channel, output logic [4095:0] data);
import "DPI-C" function int m_write_request (input byte unsigned id, input logic [4095:0] data, input shortint unsigned bitsize, input ptr_t addr, input byte unsigned shift);

function automatic integer log2;
  input integer value;
  `ifdef _SIM_HAVE_CLOG2
    log2 = $clog2(value);
  `else
    automatic integer temp_value = value-1;
    for (log2=0; temp_value > 0; log2=log2+1)
      temp_value = temp_value >> 1;
  `endif
endfunction

localparam
  CHANNELS_NUMBER = BITSIZE_Mout_oe_ram,
  BITSIZE_oe = 1,
  BITSIZE_we = 1,
  BITSIZE_addr = BITSIZE_Mout_addr_ram/CHANNELS_NUMBER,
  BITSIZE_Wsize = BITSIZE_Mout_data_ram_size/CHANNELS_NUMBER,
  BITSIZE_Wdata = BITSIZE_Mout_Wdata_ram/CHANNELS_NUMBER,
  BITSIZE_ready = 1,
  BITSIZE_Rdata = BITSIZE_M_Rdata_ram/CHANNELS_NUMBER,
  BITSIZE_tag = BITSIZE_Mout_tag/CHANNELS_NUMBER,
  BITSIZE_S_Rdata = BITSIZE_Sout_Rdata_ram/BITSIZE_S_oe_ram,
  BITSIZE_S_ready = 1,
  SLAVE_VALID = BITSIZE_Mout_oe_ram == BITSIZE_S_oe_ram;

genvar i;
integer dump_file, ramulator_profile_file, ramulator_debug_file;
wire [BITSIZE_M_DataRdy-1:0] _M_DataRdy, _M_DataRdy_reg;
wire [BITSIZE_M_Rdata_ram-1:0] _M_Rdata_ram;
wire [BITSIZE_M_tag-1:0] _M_tag;

assign S_oe_ram = Mout_oe_ram;
assign S_we_ram = Mout_we_ram;
assign S_addr_ram = Mout_addr_ram;
assign S_data_ram_size = Mout_data_ram_size;
assign S_Wdata_ram = Mout_Wdata_ram;
assign M_DataRdy = _M_DataRdy;
assign M_Rdata_ram = _M_Rdata_ram;
assign M_tag = _M_tag;

generate
  if(RAMULATOR_PROFILE)
  begin
    initial
    begin
      ramulator_profile_file = $fopen(RAMULATOR_PROFILE_FILE, "w");
      $fwrite(ramulator_profile_file, "Cycle,Channel,Operation,Address,Bitwidth,Data,Latency,Mode\n");
    end
  end

  if(RAMULATOR_DEBUG)
  begin
    initial
    begin
      ramulator_debug_file = $fopen(RAMULATOR_DEBUG_FILE, "w");
      $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Enhanced testbench initialized\n");
      $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Mode: Realistic (Ramulator)\n");
      $display("[RAMULATOR_INTEGRATED] Memory simulation mode: Realistic (Ramulator)");
    end
  end

  if(MEM_DUMP)
  begin
    initial
    begin
      dump_file = $fopen(MEM_DUMP_FILE, "w");
      $fwrite(dump_file, "Channel,Operation,Address,Bitwidth,Data,Mode\n");
    end

    always@(posedge clock)
    begin
      if(done_port)
      begin
        $fflush(dump_file);
        if(RAMULATOR_PROFILE) $fflush(ramulator_profile_file);
        if(RAMULATOR_DEBUG)
        begin
          $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Simulation completed\n");
          $fflush(ramulator_debug_file);
        end
      end
    end
  end
endgenerate

if_utils #(index, BITSIZE_Rdata) m_utils();

// Ramulator2 clock synchronization - advance memory system on each clock
reg [63:0] ramulator_cycle_counter = 0;
always @(posedge clock) begin
  if(reset == 1'b0) begin
    ramulator_cycle_counter <= 0;
  end
  else begin
    ramulator_cycle_counter <= ramulator_cycle_counter + 1;
  end
end

generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin : channel
    wire [BITSIZE_oe-1:0] oe;
    wire [BITSIZE_we-1:0] we;
    ptr_t Waddr, Raddr;
    shortint unsigned Wsize;
    wire [BITSIZE_Wdata-1:0] Wdata;
    reg [BITSIZE_ready-1:0] Wready, Rready, Wready_reg;
    reg [BITSIZE_Rdata-1:0] Rdata;
    reg [63:0] cycle_counter;
    reg [31:0] read_count, write_count;

    // Monotonic counters for outstanding request tracking (no blocking assignment needed)
    reg [15:0] total_issued, total_completed;
    wire [15:0] outstanding_count;
    assign outstanding_count = total_issued - total_completed;
    reg [63:0] idle_cycles;  // Count cycles when no requests outstanding

    // Tag-based tracking for accurate per-request latency with multiple outstanding requests
    reg [63:0] issue_cycles [0:65535];  // Map tag[15:0] -> cycle when request was issued
    reg [BITSIZE_addr-1:0] issue_addrs [0:65535];  // Map tag[15:0] -> request address

    // Bus tag echo: save request tag, return it with response (for pipelined multi-thread support)
    reg [BITSIZE_tag-1:0] Rtag, Wtag;

    // Tag map: maps driver tag[15:0] -> DUT bus tag for outstanding Ramulator requests.
    // Ramulator may reorder completions, so we index by driver tag (not FIFO).
    // Driver tags are GLOBAL (shared across all channels) and monotonically
    // increasing: 8-bit indexing aliased two same-channel reads outstanding more
    // than 256 global issues apart, misrouting the response (wrong dest/selector)
    // and losing the thread wakeup. 16 bits makes aliasing impossible in practice
    // (a read never stays outstanding across 65536 global issues).
    reg [BITSIZE_tag-1:0] tag_map [0:65535];
    wire [BITSIZE_tag-1:0] ch_M_tag;
    assign ch_M_tag = Wtag | Rtag;
    assign _M_tag[BITSIZE_tag*i+:BITSIZE_tag] = ch_M_tag;

    if(MEM_DELAY_WRITE == 1)
    begin
      always@(posedge clock)
      begin
        Wready_reg <= Wready;
      end
    end
    else
    begin
      assign Wready_reg = Wready;
    end

    // MDPI non-blocking interface: always accept requests, no back-pressure
    assign Mout_back_pressure[i] = 1'b0;

    // Statistics tracking block - only manages counters it exclusively owns
    always @(posedge clock)
    begin
      if(1RESET_VALUE)
      begin
        cycle_counter <= 0;
        read_count <= 0;
        write_count <= 0;
      end
      else
      begin
        cycle_counter <= cycle_counter + 1;
        if(oe && base_addr <= Raddr) read_count <= read_count + 1;
        if(we && base_addr <= Waddr) write_count <= write_count + 1;
      end
    end

    // Direct connection - no queue needed for MDPI non-blocking interface
    assign oe = Mout_oe_ram[BITSIZE_oe*i+:BITSIZE_oe];
    assign Raddr = Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr];

    assign _M_DataRdy[BITSIZE_ready*i+:BITSIZE_ready] = Wready | Rready | (Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1);
    assign _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready] = Wready_reg | Rready;
    assign _M_Rdata_ram[BITSIZE_Rdata*i+:BITSIZE_Rdata] = Rdata | (Sout_Rdata_ram[BITSIZE_S_Rdata*i*SLAVE_VALID+:BITSIZE_S_Rdata] & {BITSIZE_S_Rdata{Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1}});

    begin : read_channel
      // Cycle-accurate Ramulator2 timing: separate request issuance from completion
      always@(posedge clock)
      begin : read_channel_always
        automatic reg [BITSIZE_Rdata-1:0] data;
        automatic logic [4095:0] dpi_data;
        automatic int request_result;
        automatic int completed_driver_tag;

        // One-cycle pulse: reset every cycle, set when completion arrives
        Rready <= 0;
        Rdata <= 0;
        Rtag <= 0;

        if(1RESET_VALUE)
        begin
          total_issued <= 0;
          total_completed <= 0;
          idle_cycles <= 0;
        end
        else
        begin
          // Count idle cycles only when truly idle (no outstanding reads AND no active writes)
          // When has_any_activity is true, the global state() tick already advances Ramulator
          if(outstanding_count == 0 && !has_any_activity)
            idle_cycles <= idle_cycles + 1;

          // Issue new read request (accept every cycle oe is high - pipelined bus protocol)
          if(oe && base_addr <= Raddr)
          begin
            if(outstanding_count == 0 && idle_cycles > 0 && !has_any_activity)
            begin
              // Fast-forward idle cycles only when NO channels have any activity
              void'(m_utils.state(32'h80000000 | idle_cycles));
              idle_cycles <= 0;
            end

            request_result = m_read_request(index, BITSIZE_Rdata, Raddr, i[7:0]);
            if(request_result > 0)
            begin
              total_issued <= total_issued + 1;

              // Map driver tag -> DUT bus tag (Ramulator may reorder completions)
              tag_map[request_result[15:0]] <= Mout_tag[BITSIZE_tag*i+:BITSIZE_tag];

              // Store timing info by tag for accurate latency calculation
              issue_cycles[request_result[15:0]] <= cycle_counter;
              issue_addrs[request_result[15:0]] <= Raddr;

              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Cycle %0d: Issued read request tag %0d to addr 0x%h\n",
                       cycle_counter, request_result, Raddr);
              end
            end
            else
            begin
              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Cycle %0d: Read request rejected (Ramulator2 buffer full)\n", cycle_counter);
              end
            end
          end

          // Check for completion of outstanding request (every cycle)
          // Skip polling when a write is active: both Wready and Rready in
          // the same cycle would corrupt M_tag (ch_M_tag = Wtag | Rtag).
          // The completion stays in the driver's queue until next cycle.
          if(outstanding_count > 0 && !(we && base_addr <= Waddr))
          begin
            completed_driver_tag = m_read_complete_ch(index, i[7:0], dpi_data);
            if(completed_driver_tag > 0)
            begin
              data = dpi_data[BITSIZE_Rdata-1:0];
              Rdata <= data;
              Rready <= 1;
              Rtag <= tag_map[completed_driver_tag[15:0]];  // Look up DUT tag by driver tag
              total_completed <= total_completed + 1;

              if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,%0d,READ,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, i, Raddr, BITSIZE_Rdata, data);
              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Cycle %0d: Read completed (driver_tag=%0d), data=0x%X\n",
                       cycle_counter, completed_driver_tag, data);
              end
            end
          end
        end
      end
    end

    // Direct write connections for MDPI
    assign we = Mout_we_ram[BITSIZE_we*i+:BITSIZE_we];
    assign Waddr = Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr];
    assign Wsize = {{16-BITSIZE_Wsize{1'b0}}, Mout_data_ram_size[BITSIZE_Wsize*i+:BITSIZE_Wsize]};
    assign Wdata = Mout_Wdata_ram[BITSIZE_Wdata*i+:BITSIZE_Wdata];

    // MDPI write channel - Ramulator DPI-C write request
    begin : write_channel
      always@(posedge clock)
      begin : write_channel_always
        automatic logic [4095:0] dpi_data;
        Wready <= 0;
        Wtag <= 0;
        if(we && base_addr <= Waddr)
        begin
          dpi_data = {{4096-BITSIZE_Wdata{1'b0}}, Wdata};
          if(m_write_request(index, dpi_data, BITSIZE_Wdata, Waddr, 0) > 0)
          begin
            Wready <= 1;
            Wtag <= Mout_tag[BITSIZE_tag*i+:BITSIZE_tag];
            if(MEM_DUMP) $fwrite(dump_file, "%0d,w,0x%X,%0d,0x%X,REALISTIC\n", i, Waddr, Wsize, Wdata);
            if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,%0d,WRITE,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, i, Waddr, Wsize, Wdata);
          end
        end
      end
    end

    always @(posedge clock)
    begin
      if (we & oe)
      begin
        $display("ERROR - Mout_we_ram and Mout_oe_ram both enabled on channel %0d!", i);
        $finish;
      end
    end

    if(RAMULATOR_DEBUG)
    begin
      always @(posedge clock)
      begin
        if(cycle_counter % 10000 == 0 && cycle_counter > 0)
        begin
          $fwrite(ramulator_debug_file, "[RAMULATOR_INTEGRATED] Progress: Cycle %0d, Ch:%0d Reads:%0d Writes:%0d Mode:Realistic\n", cycle_counter, i, read_count, write_count);
        end
      end
    end
  end
endgenerate

// Global multi-channel coordination (prevents race conditions)
wire has_any_outstanding;
wire has_any_writing;
wire has_any_activity;
reg global_idle_consumed;

// Simple scalable approach using packed array and reduction operators
wire [CHANNELS_NUMBER-1:0] channel_busy;
wire [CHANNELS_NUMBER-1:0] channel_writing;
genvar j;
generate
  for(j = 0; j < CHANNELS_NUMBER; j++) begin : check_busy
    assign channel_busy[j] = (channel[j].outstanding_count > 0);
    assign channel_writing[j] = (channel[j].we && base_addr <= channel[j].Waddr);
  end
endgenerate

// Clean reduction OR - works for any number of channels automatically
assign has_any_outstanding = |channel_busy;
assign has_any_writing = |channel_writing;
assign has_any_activity = has_any_outstanding | has_any_writing;

// Global clock coordination - exactly one state() call per cycle
// Must advance Ramulator during both read AND write phases to prevent deadlock:
// Without ticking during write-only bursts, Ramulator's internal buffers fill up,
// writes get rejected, and the hardware stalls indefinitely.
always @(posedge clock) begin
  global_idle_consumed <= 1'b0;  // Reset flag each cycle

  if(has_any_activity) begin
    // Active requests or writes: advance Ramulator exactly 1 cycle
    void'(m_utils.state(32'h80000001));  // Single coordinated tick
  end
end

import "DPI-C" function int m_read_request (input byte unsigned id, input shortint unsigned bitsize, input ptr_t addr, input byte cmd);
import "DPI-C" function int m_read_complete (input byte unsigned id, output logic [4095:0] data);
import "DPI-C" function int m_read_complete_ch (input byte unsigned id, input byte unsigned channel, output logic [4095:0] data);
import "DPI-C" function int m_write_request (input byte unsigned id, input logic [4095:0] data, input shortint unsigned bitsize, input ptr_t addr, input byte unsigned shift);

function automatic integer log2;
  input integer value;
  `ifdef _SIM_HAVE_CLOG2
    log2 = $clog2(value);
  `else
    automatic integer temp_value = value-1;
    for (log2=0; temp_value > 0; log2=log2+1)
      temp_value = temp_value >> 1;
  `endif
endfunction

localparam
  CHANNELS_NUMBER = BITSIZE_Mout_oe_ram,
  BITSIZE_oe = 1,
  BITSIZE_we = 1,
  BITSIZE_addr = BITSIZE_Mout_addr_ram/CHANNELS_NUMBER,
  BITSIZE_Wsize = BITSIZE_Mout_data_ram_size/CHANNELS_NUMBER,
  BITSIZE_Wdata = BITSIZE_Mout_Wdata_ram/CHANNELS_NUMBER,
  BITSIZE_ready = 1,
  BITSIZE_Rdata = BITSIZE_M_Rdata_ram/CHANNELS_NUMBER,
  BITSIZE_tag = BITSIZE_Mout_tag/CHANNELS_NUMBER,
  BITSIZE_S_Rdata = BITSIZE_Sout_Rdata_ram/BITSIZE_S_oe_ram,
  BITSIZE_S_ready = 1,
  SLAVE_VALID = BITSIZE_Mout_oe_ram == BITSIZE_S_oe_ram;

genvar i;
integer dump_file, ramulator_profile_file, ramulator_debug_file;
wire [BITSIZE_M_DataRdy-1:0] _M_DataRdy, _M_DataRdy_reg;
wire [BITSIZE_M_Rdata_ram-1:0] _M_Rdata_ram;
wire [BITSIZE_M_tag-1:0] _M_tag;

assign S_oe_ram = Mout_oe_ram;
assign S_we_ram = Mout_we_ram;
assign S_addr_ram = Mout_addr_ram;
assign S_data_ram_size = Mout_data_ram_size;
assign S_Wdata_ram = Mout_Wdata_ram;
assign M_DataRdy = _M_DataRdy;
assign M_Rdata_ram = _M_Rdata_ram;
assign M_tag = _M_tag;

generate
  if(RAMULATOR_PROFILE)
  begin
    initial
    begin
      ramulator_profile_file = $fopen(RAMULATOR_PROFILE_FILE, "w");
      $fwrite(ramulator_profile_file, "Cycle,Channel,Operation,Address,Bitwidth,Data,Latency,Mode\n");
    end
  end

  if(RAMULATOR_DEBUG)
  begin
    initial
    begin
      ramulator_debug_file = $fopen(RAMULATOR_DEBUG_FILE, "w");
      $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Enhanced testbench initialized\n");
      $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Mode: Realistic (Ramulator) with NoC back-pressure\n");
      $display("[RAMULATOR_NOC] Memory simulation mode: Realistic (Ramulator) with NoC back-pressure");
    end
  end

  if(MEM_DUMP)
  begin
    initial
    begin
      dump_file = $fopen(MEM_DUMP_FILE, "w");
      $fwrite(dump_file, "Channel,Operation,Address,Bitwidth,Data,Mode\n");
    end

    always@(posedge clock)
    begin
      if(done_port)
      begin
        $fflush(dump_file);
        if(RAMULATOR_PROFILE) $fflush(ramulator_profile_file);
        if(RAMULATOR_DEBUG)
        begin
          $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Simulation completed\n");
          $fflush(ramulator_debug_file);
        end
      end
    end
  end
endgenerate

if_utils #(index, BITSIZE_Rdata) m_utils();

// Ramulator2 clock synchronization - advance memory system on each clock
reg [63:0] ramulator_cycle_counter = 0;
always @(posedge clock) begin
  if(reset == 1'b0) begin
    ramulator_cycle_counter <= 0;
  end
  else begin
    ramulator_cycle_counter <= ramulator_cycle_counter + 1;
  end
end

generate
  for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
  begin : channel
    wire [BITSIZE_oe-1:0] oe;
    wire [BITSIZE_we-1:0] we;
    ptr_t Waddr, Raddr;
    shortint unsigned Wsize;
    wire [BITSIZE_Wdata-1:0] Wdata;
    reg [BITSIZE_ready-1:0] Wready, Rready, Wready_reg;
    reg [BITSIZE_Rdata-1:0] Rdata;
    reg [63:0] cycle_counter;
    reg [31:0] read_count, write_count;

    // Monotonic counters for outstanding request tracking (no blocking assignment needed)
    reg [15:0] total_issued, total_completed;
    wire [15:0] outstanding_count;
    assign outstanding_count = total_issued - total_completed;
    reg [63:0] idle_cycles;  // Count cycles when no requests outstanding

    // Tag-based tracking for accurate per-request latency with multiple outstanding requests
    reg [63:0] issue_cycles [0:65535];  // Map tag[15:0] -> cycle when request was issued
    reg [BITSIZE_addr-1:0] issue_addrs [0:65535];  // Map tag[15:0] -> request address

    // Bus tag echo: save request tag, return it with response (for pipelined multi-thread support)
    reg [BITSIZE_tag-1:0] Rtag, Wtag;

    // Tag map: maps driver tag[15:0] -> DUT bus tag for outstanding Ramulator requests.
    // Ramulator may reorder completions, so we index by driver tag (not FIFO).
    // Driver tags are GLOBAL (shared across all channels) and monotonically
    // increasing: 8-bit indexing aliased two same-channel reads outstanding more
    // than 256 global issues apart, misrouting the response (wrong dest/selector)
    // and losing the thread wakeup. 16 bits makes aliasing impossible in practice
    // (a read never stays outstanding across 65536 global issues).
    reg [BITSIZE_tag-1:0] tag_map [0:65535];
    wire [BITSIZE_tag-1:0] ch_M_tag;
    assign ch_M_tag = Wtag | Rtag;
    assign _M_tag[BITSIZE_tag*i+:BITSIZE_tag] = ch_M_tag;

    // Response buffering: M_back_pressure[i] is the response NoC's input
    // back-pressure (noc_from_memory i_bp). When high, the response NoC
    // can't accept data — pushing valid data when i_bp is high causes the
    // io_node6 to silently drop it. We must buffer completed reads/writes
    // and only assert Rready/Wready when M_back_pressure[i] is low.
    // Response delivery FIFOs (depth 256). Read data and write acks both travel
    // the bufferless response NoC, which silently drops anything pushed while
    // M_back_pressure[i] is high. We therefore NEVER stall the request path on
    // response state; every completed read / accepted write ack is queued here
    // and drained at most one per cycle when the response NoC can accept it.
    // 256 = the 8-bit driver-tag space, so at most 256 reads can be outstanding
    // and the read FIFO can never overflow; the write FIFO matches. These are
    // behavioral (sim-only) FIFOs — this is a co-sim testbench, not synthesized.
    localparam RFIFO_DEPTH = 256;
    reg [BITSIZE_Rdata-1:0] rfifo_data [0:RFIFO_DEPTH-1];
    reg [BITSIZE_tag-1:0]   rfifo_tag  [0:RFIFO_DEPTH-1];
    reg [7:0] rfifo_head, rfifo_tail;
    reg [8:0] rfifo_count;
    reg [BITSIZE_tag-1:0]   wfifo_tag  [0:RFIFO_DEPTH-1];
    reg [7:0] wfifo_head, wfifo_tail;
    reg [8:0] wfifo_count;

    // Skid-buffer delivery discipline against the response NoC's COMBINATIONAL
    // inject back-pressure (io_node6: i_bp = i_valid && ...). M_back_pressure[i]
    // means "the flit presented THIS cycle is rejected"; it can only be high
    // while we assert Rready/Wready. The registered Rready/Rdata/Rtag/Wready/
    // Wtag outputs form the skid stage: on rejection they are HELD unchanged and
    // re-presented next cycle (lossless retry); a FIFO head is advanced only
    // when a new flit is loaded into the free output stage, so nothing is ever
    // dequeued before the NoC has accepted the previous flit. Write acks take
    // priority (reads wait) so Rready and Wready — which share
    // ch_M_tag = Wtag|Rtag and M_DataRdy — can never assert in the same cycle.
    // M_back_pressure[i] is consumed ONLY inside sequential always blocks, so no
    // combinational i_bp <-> i_valid loop is created.
    wire out_valid = (Rready != 0) || (Wready != 0);
    wire rejected  = out_valid && M_back_pressure[i];
    wire wack_load = !rejected && (wfifo_count != 0);
    wire rd_load   = !rejected && !wack_load && (rfifo_count != 0);

    if(MEM_DELAY_WRITE == 1)
    begin
      always@(posedge clock)
      begin
        Wready_reg <= Wready;
      end
    end
    else
    begin
      assign Wready_reg = Wready;
    end

    // Request-path back-pressure: held at 0 (always accept requests from the
    // request NoC). The response FIFOs above can never overflow — the read FIFO
    // is bounded by the 256-entry driver-tag space and the write FIFO matches —
    // so the request path never needs to stall on response state. Decoupling
    // request acceptance from response drain is exactly what prevents the
    // multi-channel deadlock: tying Mout_back_pressure to a pending-response flag
    // couples the request NoC to the response NoC, and because the DUT core gates
    // its own request injection on response acceptance, that closes a circular
    // wait (request held -> core can't inject -> core won't drain the response
    // NoC -> M_back_pressure[i] stays high -> request stays held, forever).
    // M_back_pressure[i] (the response NoC i_bp) still affects DELIVERY only:
    // a rejected flit is held in the registered skid stage and retried, so
    // io_node6 never silently drops a response.
    assign Mout_back_pressure[i] = 1'b0;

    // Statistics tracking block - only manages counters it exclusively owns
    always @(posedge clock)
    begin
      if(1RESET_VALUE)
      begin
        cycle_counter <= 0;
        read_count <= 0;
        write_count <= 0;
      end
      else
      begin
        cycle_counter <= cycle_counter + 1;
        if(oe && base_addr <= Raddr) read_count <= read_count + 1;
        if(we && base_addr <= Waddr) write_count <= write_count + 1;
      end
    end

    // Direct connection - no queue needed for MDPI non-blocking interface
    assign oe = Mout_oe_ram[BITSIZE_oe*i+:BITSIZE_oe];
    assign Raddr = Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr];

    assign _M_DataRdy[BITSIZE_ready*i+:BITSIZE_ready] = Wready | Rready | (Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1);
    assign _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready] = Wready_reg | Rready;
    assign _M_Rdata_ram[BITSIZE_Rdata*i+:BITSIZE_Rdata] = Rdata | (Sout_Rdata_ram[BITSIZE_S_Rdata*i*SLAVE_VALID+:BITSIZE_S_Rdata] & {BITSIZE_S_Rdata{Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1}});

    begin : read_channel
      // Cycle-accurate Ramulator2 timing. Issuance and completion are fully
      // decoupled from delivery: requests are accepted and completions are
      // polled EVERY cycle (never gated on response-buffer state, so a request
      // can never be dropped). Each completed read is queued in rfifo (or, when
      // the FIFO is empty and the output stage is free, bypassed straight into
      // it) and drained one per cycle by the arbiter (rd_load) when the skid
      // output stage is free to take a new flit.
      always@(posedge clock)
      begin : read_channel_always
        automatic reg [BITSIZE_Rdata-1:0] data;
        automatic logic [4095:0] dpi_data;
        automatic int request_result;
        automatic int completed_driver_tag;
        automatic reg do_push;
        do_push = 1'b0;

        // Skid output stage: when this cycle's flit is rejected (rejected==1),
        // HOLD Rready/Rdata/Rtag unchanged so the same flit is re-presented next
        // cycle. Otherwise default-clear and (re)load below.
        if(!rejected)
        begin
          Rready <= 0;
          Rdata <= 0;
          Rtag <= 0;
        end

        if(1RESET_VALUE)
        begin
          total_issued <= 0;
          total_completed <= 0;
          idle_cycles <= 0;
          rfifo_head <= 0;
          rfifo_tail <= 0;
          rfifo_count <= 0;
          Rready <= 0;
          Rdata <= 0;
          Rtag <= 0;
        end
        else
        begin
          // Count idle cycles only when truly idle: no outstanding reads, no
          // active write, and nothing queued for delivery (has_any_activity
          // includes the FIFOs). The global state() tick advances Ramulator
          // whenever has_any_activity is true.
          if(outstanding_count == 0 && !has_any_activity)
            idle_cycles <= idle_cycles + 1;

          // Issue new read request (accept every cycle oe is high - pipelined bus protocol)
          if(oe && base_addr <= Raddr)
          begin
            if(outstanding_count == 0 && idle_cycles > 0 && !has_any_activity)
            begin
              // Fast-forward idle cycles only when NO channels have any activity
              void'(m_utils.state(32'h80000000 | idle_cycles));
              idle_cycles <= 0;
            end

            request_result = m_read_request(index, BITSIZE_Rdata, Raddr, i[7:0]);
            if(request_result > 0)
            begin
              total_issued <= total_issued + 1;

              // Map driver tag -> DUT bus tag (Ramulator may reorder completions)
              tag_map[request_result[15:0]] <= Mout_tag[BITSIZE_tag*i+:BITSIZE_tag];

              // Store timing info by tag for accurate latency calculation
              issue_cycles[request_result[15:0]] <= cycle_counter;
              issue_addrs[request_result[15:0]] <= Raddr;

              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Issued read request tag %0d to addr 0x%h\n",
                       cycle_counter, request_result, Raddr);
              end
            end
            else
            begin
              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Read request rejected (Ramulator2 buffer full)\n", cycle_counter);
              end
            end
          end

          // Poll for completion every cycle and ENQUEUE it for delivery. Polling
          // no longer needs to skip write-active cycles: it only pushes to the
          // FIFO (never asserts Rready), and the arbiter below guarantees Rready
          // and Wready never coincide.
          if(outstanding_count > 0)
          begin
            completed_driver_tag = m_read_complete_ch(index, i[7:0], dpi_data);
            if(completed_driver_tag > 0)
            begin
              data = dpi_data[BITSIZE_Rdata-1:0];
              total_completed <= total_completed + 1;

              if(!rejected && !wack_load && rfifo_count == 0)
              begin
                // Empty-FIFO bypass: the skid output stage is free this edge and
                // nothing is queued ahead of us, so hand the fresh completion
                // straight to the registered output stage (still one registered
                // stage - never a same-cycle combinational handoff).
                Rdata <= data;
                Rready <= 1;
                Rtag <= tag_map[completed_driver_tag[15:0]];
              end
              else
              begin
                if(rfifo_count == RFIFO_DEPTH)
                begin
                  $display("ERROR - read response FIFO overflow on channel %0d", i);
                  $finish;
                end
                rfifo_data[rfifo_tail] <= data;
                rfifo_tag[rfifo_tail]  <= tag_map[completed_driver_tag[15:0]];
                rfifo_tail <= rfifo_tail + 8'd1;
                do_push = 1'b1;
              end

              if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,%0d,READ,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, i, Raddr, BITSIZE_Rdata, data);
              if(RAMULATOR_DEBUG)
              begin
                $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Read completed (driver_tag=%0d), data=0x%X\n",
                       cycle_counter, completed_driver_tag, data);
              end
            end
          end

          // Load one queued read response into the free skid output stage.
          // rd_load requires !rejected (output stage free next edge) and
          // rfifo_count != 0 (registered), so the head is advanced only when the
          // flit moves into the output register - a rejected flit is never lost
          // and a queued flit is never skipped (head != tail while count > 0, so
          // the pop read and a concurrent push write hit different entries).
          if(rd_load)
          begin
            Rdata <= rfifo_data[rfifo_head];
            Rready <= 1;
            Rtag <= rfifo_tag[rfifo_head];
            rfifo_head <= rfifo_head + 8'd1;
            if(RAMULATOR_DEBUG)
              $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Delivered read response, data=0x%X\n",
                     cycle_counter, rfifo_data[rfifo_head]);
          end

          // Net occupancy update (a push and a pop may both happen this cycle).
          rfifo_count <= rfifo_count + (do_push ? 9'd1 : 9'd0) - (rd_load ? 9'd1 : 9'd0);
        end
      end
    end

    // Direct write connections for MDPI
    assign we = Mout_we_ram[BITSIZE_we*i+:BITSIZE_we];
    assign Waddr = Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr];
    assign Wsize = {{16-BITSIZE_Wsize{1'b0}}, Mout_data_ram_size[BITSIZE_Wsize*i+:BITSIZE_Wsize]};
    assign Wdata = Mout_Wdata_ram[BITSIZE_Wdata*i+:BITSIZE_Wdata];

    // MDPI write channel. The DPI write commits the data immediately; only the
    // ack travels the response NoC. Writes are accepted EVERY cycle we is high
    // (never stalled on response state) and their acks are queued in wfifo,
    // drained one per cycle by wack_load, which has priority over read
    // delivery so Rready/Wready never coincide.
    begin : write_channel
      always@(posedge clock)
      begin : write_channel_always
        automatic logic [4095:0] dpi_data;
        automatic reg do_wpush;
        do_wpush = 1'b0;
        // Skid discipline: if the presented flit was rejected this cycle, HOLD
        // Wready/Wtag (skip the default clears) and retry next cycle.
        if(!rejected)
        begin
          Wready <= 0;
          Wtag <= 0;
        end

        if(1RESET_VALUE)
        begin
          Wready <= 0;
          Wtag <= 0;
          wfifo_head <= 0;
          wfifo_tail <= 0;
          wfifo_count <= 0;
        end
        else
        begin
          // Accept a write every cycle we is high; commit it and queue its ack.
          if(we && base_addr <= Waddr)
          begin
            dpi_data = {{4096-BITSIZE_Wdata{1'b0}}, Wdata};
            // Use the actual access size (Mout_data_ram_size), not the full channel
            // width: sub-word stores (e.g. byte writes) must not clobber neighbours.
            if(m_write_request(index, dpi_data, Wsize, Waddr, 0) > 0)
            begin
              if(wfifo_count == RFIFO_DEPTH)
              begin
                $display("ERROR - write ack FIFO overflow on channel %0d", i);
                $finish;
              end
              wfifo_tag[wfifo_tail] <= Mout_tag[BITSIZE_tag*i+:BITSIZE_tag];
              wfifo_tail <= wfifo_tail + 8'd1;
              do_wpush = 1'b1;
              if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Write accepted ch=%0d tag=%0d addr=0x%h wfifo_count=%0d bp=%0d\n", cycle_counter, i, Mout_tag[BITSIZE_tag*i+:BITSIZE_tag], Waddr, wfifo_count, M_back_pressure[i]);
              if(MEM_DUMP) $fwrite(dump_file, "%0d,w,0x%X,%0d,0x%X,REALISTIC\n", i, Waddr, Wsize, Wdata);
              if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,%0d,WRITE,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, i, Waddr, Wsize, Wdata);
            end
          end

          // Load one queued write ack into the free skid output stage (write
          // acks have priority over read delivery so Rready/Wready never
          // coincide). wack_load requires !rejected, so the head advances only
          // when the ack moves into the output register - a rejected ack is
          // held and retried, never lost.
          if(wack_load)
          begin
            Wready <= 1;
            Wtag <= wfifo_tag[wfifo_head];
            wfifo_head <= wfifo_head + 8'd1;
            if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Cycle %0d: Write ack delivered ch=%0d tag=%0d wfifo_count=%0d\n", cycle_counter, i, wfifo_tag[wfifo_head], wfifo_count);
          end

          wfifo_count <= wfifo_count + (do_wpush ? 9'd1 : 9'd0) - (wack_load ? 9'd1 : 9'd0);
        end
      end
    end

    always @(posedge clock)
    begin
      if (we & oe)
      begin
        $display("ERROR - Mout_we_ram and Mout_oe_ram both enabled on channel %0d!", i);
        $finish;
      end
    end

    if(RAMULATOR_DEBUG)
    begin
      always @(posedge clock)
      begin
        if(cycle_counter % 10000 == 0 && cycle_counter > 0)
        begin
          $fwrite(ramulator_debug_file, "[RAMULATOR_NOC] Progress: Cycle %0d, Ch:%0d Reads:%0d Writes:%0d bp=%0d rfifo=%0d wfifo=%0d outst=%0d Mode:Realistic\n", cycle_counter, i, read_count, write_count, M_back_pressure[i], rfifo_count, wfifo_count, outstanding_count);
        end
      end
    end
  end
endgenerate

// Global multi-channel coordination (prevents race conditions)
wire has_any_outstanding;
wire has_any_writing;
wire has_any_pending;
wire has_any_activity;
reg global_idle_consumed;

// Simple scalable approach using packed array and reduction operators
wire [CHANNELS_NUMBER-1:0] channel_busy;
wire [CHANNELS_NUMBER-1:0] channel_writing;
wire [CHANNELS_NUMBER-1:0] channel_pending;
genvar j;
generate
  for(j = 0; j < CHANNELS_NUMBER; j++) begin : check_busy
    assign channel_busy[j] = (channel[j].outstanding_count > 0);
    assign channel_writing[j] = (channel[j].we && base_addr <= channel[j].Waddr);
    assign channel_pending[j] = (channel[j].rfifo_count != 0) | (channel[j].wfifo_count != 0);
  end
endgenerate

// Clean reduction OR - works for any number of channels automatically
assign has_any_outstanding = |channel_busy;
assign has_any_writing = |channel_writing;
assign has_any_pending = |channel_pending;
assign has_any_activity = has_any_outstanding | has_any_writing | has_any_pending;

// Global clock coordination - exactly one state() call per cycle
// Must advance Ramulator during both read AND write phases to prevent deadlock:
// Without ticking during write-only bursts, Ramulator's internal buffers fill up,
// writes get rejected, and the hardware stalls indefinitely.
// Also tick while pending responses wait for back-pressure to clear.
always @(posedge clock) begin
  global_idle_consumed <= 1'b0;  // Reset flag each cycle

  if(has_any_activity) begin
    // Active requests or writes: advance Ramulator exactly 1 cycle
    void'(m_utils.state(32'h80000001));  // Single coordinated tick
  end
end

import "DPI-C" function int m_read_request (input byte unsigned id, input shortint unsigned bitsize, input ptr_t addr, input byte cmd);
import "DPI-C" function int m_read_complete (input byte unsigned id, output logic [4095:0] data);
import "DPI-C" function int m_read_complete_ch (input byte unsigned id, input byte unsigned channel, output logic [4095:0] data);
import "DPI-C" function int m_write_request (input byte unsigned id, input logic [4095:0] data, input shortint unsigned bitsize, input ptr_t addr, input byte unsigned shift);

function automatic integer log2;
  input integer value;
  `ifdef _SIM_HAVE_CLOG2
    log2 = $clog2(value);
  `else
    automatic integer temp_value = value-1;
    for (log2=0; temp_value > 0; log2=log2+1)
      temp_value = temp_value >> 1;
  `endif
endfunction

localparam BITSIZE_data = BITSIZE_rdata,
  BITSIZE_addr = BITSIZE_araddr,
  BITSIZE_id = BITSIZE_arid;

integer dump_file, ramulator_profile_file, ramulator_debug_file;

if_utils #(index, BITSIZE_data) m_utils();

// Output registers
reg arready_reg;
reg [BITSIZE_rid-1:0] rid_reg;
reg [BITSIZE_rdata-1:0] rdata_reg;
reg [BITSIZE_rresp-1:0] rresp_reg;
reg [BITSIZE_ruser-1:0] ruser_reg;
reg rlast_reg;
reg rvalid_reg;

reg awready_reg;
reg wready_reg;
reg [BITSIZE_bid-1:0] bid_reg;
reg [BITSIZE_bresp-1:0] bresp_reg;
reg [BITSIZE_buser-1:0] buser_reg;
reg bvalid_reg;

assign arready = arready_reg;
assign rid = rid_reg;
assign rdata = rdata_reg;
assign rresp = rresp_reg;
assign ruser = ruser_reg;
assign rlast = rlast_reg;
assign rvalid = rvalid_reg;
assign awready = awready_reg;
assign wready = wready_reg;
assign bid = bid_reg;
assign bresp = bresp_reg;
assign buser = buser_reg;
assign bvalid = bvalid_reg;

// Monotonic counters for outstanding read tracking
reg [15:0] total_issued, total_completed;
wire [15:0] outstanding_count;
assign outstanding_count = total_issued - total_completed;
reg [63:0] idle_cycles;
reg [63:0] cycle_counter;
reg [31:0] read_count, write_count;

// Tag map: maps driver tag[15:0] -> AXI transaction ID for outstanding Ramulator requests.
// Driver tags are global and monotonically increasing; 16-bit indexing avoids the
// aliasing that 8-bit indexing allowed for long-outstanding reads.
reg [BITSIZE_id-1:0] tag_map [0:65535];
reg [63:0] issue_cycles [0:65535];
reg [BITSIZE_addr-1:0] issue_addrs [0:65535];

// Pending read response buffer (AXI requires holding RVALID until RREADY)
reg pending_rvalid;
reg [BITSIZE_data-1:0] pending_rdata;
reg [BITSIZE_id-1:0] pending_rid;

// Pending write response buffer (AXI requires holding BVALID until BREADY)
reg pending_bvalid;
reg [BITSIZE_id-1:0] pending_bid;

// Activity tracking for Ramulator clock coordination
wire has_any_outstanding;
wire has_any_writing;
wire has_any_pending;
wire has_any_activity;
assign has_any_outstanding = (outstanding_count > 0);
assign has_any_writing = (awvalid && wvalid && awready_reg && wready_reg);
assign has_any_pending = pending_rvalid | pending_bvalid;
assign has_any_activity = has_any_outstanding | has_any_writing | has_any_pending;

// Profiling and debug file initialization
generate
  if(RAMULATOR_PROFILE)
  begin
    initial
    begin
      ramulator_profile_file = $fopen(RAMULATOR_PROFILE_FILE, "w");
      $fwrite(ramulator_profile_file, "Cycle,Channel,Operation,Address,Bitwidth,Data,Latency,Mode\n");
    end
  end

  if(RAMULATOR_DEBUG)
  begin
    initial
    begin
      ramulator_debug_file = $fopen(RAMULATOR_DEBUG_FILE, "w");
      $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Testbench initialized\n");
      $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Mode: Realistic (Ramulator) via AXI4\n");
      $display("[AXI_RAMULATOR] Memory simulation mode: Realistic (Ramulator) via AXI4");
    end
  end

  if(MEM_DUMP)
  begin
    initial
    begin
      dump_file = $fopen(MEM_DUMP_FILE, "w");
      $fwrite(dump_file, "Channel,Operation,Address,Bitwidth,Data,Mode\n");
    end

    final
    begin
      $fflush(dump_file);
      if(RAMULATOR_PROFILE) $fflush(ramulator_profile_file);
      if(RAMULATOR_DEBUG)
      begin
        $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Simulation completed\n");
        $fflush(ramulator_debug_file);
      end
    end
  end
endgenerate

// Cycle counter
always @(posedge clock) begin
  if(reset == 1'b0) begin
    cycle_counter <= 0;
    read_count <= 0;
    write_count <= 0;
  end
  else begin
    cycle_counter <= cycle_counter + 1;
  end
end

// ============================================================
// READ PATH: AR channel accept -> m_read_request -> m_read_complete_ch -> R channel
// ============================================================
always @(posedge clock) begin : read_path
  automatic logic [4095:0] dpi_data;
  automatic int request_result;
  automatic int completed_driver_tag;
  automatic reg [BITSIZE_data-1:0] data;

  if(1RESET_VALUE) begin
    arready_reg <= 0;
    rvalid_reg <= 0;
    rdata_reg <= 0;
    rid_reg <= 0;
    rresp_reg <= 0;
    ruser_reg <= 0;
    rlast_reg <= 0;
    total_issued <= 0;
    total_completed <= 0;
    idle_cycles <= 0;
    pending_rvalid <= 0;
    pending_rdata <= 0;
    pending_rid <= 0;
  end
  else begin
    // -------- R channel: clear when master accepts current response --------
    if(rvalid_reg && rready) begin
      rvalid_reg <= 1'b0;
      rdata_reg  <= 0;
      rid_reg    <= 0;
      rlast_reg  <= 1'b0;
    end

    // -------- Promote pending buffer to R channel when channel is free -----
    if(pending_rvalid && (!rvalid_reg || rready)) begin
      rvalid_reg     <= 1'b1;
      rdata_reg      <= pending_rdata;
      rid_reg        <= pending_rid;
      rlast_reg      <= 1'b1;
      rresp_reg      <= 2'b00;
      pending_rvalid <= 1'b0;
    end

    // ------- Poll Ramulator for read completions -------
    // Issue #3 fix: previous guard `!rvalid_reg` was redundant with the same
    // term in an inner if, making the pending_rvalid buffer branch dead
    // code. Guarding on `!pending_rvalid` instead makes both routes
    // reachable: live R channel when free, buffer when master is holding.
    if(outstanding_count > 0 && !pending_rvalid) begin
      // Channel-collision fix: MEM-channel testbenches use driver channels
      // 0..CHANNELS_NUMBER-1 on the same interface id; sharing channel 0 with
      // AXI_PORT_ID=0 makes both TBs pop each other's completions from the
      // shared per-channel FIFO (lost read -> DUT deadlock). Offset the AXI
      // port into a disjoint channel namespace (0x80 | port).
      completed_driver_tag = m_read_complete_ch(index, (8'h80 | AXI_PORT_ID[7:0]), dpi_data);
      if(completed_driver_tag > 0) begin
        data = dpi_data[BITSIZE_data-1:0];
        // Issue #2 fix: guard against underflow on a spurious completion.
        if(total_completed != total_issued)
          total_completed <= total_completed + 1;

        if(!rvalid_reg || rready) begin
          // R channel free (or accepted this cycle) -- drive directly
          rvalid_reg <= 1'b1;
          rdata_reg  <= data;
          rid_reg    <= tag_map[completed_driver_tag[15:0]];
          rlast_reg  <= 1'b1;
          rresp_reg  <= 2'b00;
        end
        else begin
          // R channel held by master -- stage in pending buffer
          pending_rvalid <= 1'b1;
          pending_rdata  <= data;
          pending_rid    <= tag_map[completed_driver_tag[15:0]];
        end

        if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,0,READ,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, issue_addrs[completed_driver_tag[15:0]], BITSIZE_data, data);
        if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Cycle %0d: Read completed (driver_tag=%0d), data=0x%X\n", cycle_counter, completed_driver_tag, data);
      end
    end

    // ------- Accept new AR requests -------
    if(outstanding_count == 0 && !has_any_activity)
      idle_cycles <= idle_cycles + 1;

    // Issue #1 fix: single-source assignment of arready_reg from a complete
    // decision tree, replacing the previous default-then-override pattern
    // that drove arready_reg twice within this always block.
    if(arvalid && arready_reg) begin
      if(outstanding_count == 0 && idle_cycles > 0 && !has_any_activity) begin
        void'(m_utils.state(32'h80000000 | idle_cycles));
        idle_cycles <= 0;
      end

      request_result = m_read_request(index, BITSIZE_data, araddr, (8'h80 | AXI_PORT_ID[7:0]));
      if(request_result > 0) begin
        total_issued <= total_issued + 1;
        read_count   <= read_count + 1;
        tag_map[request_result[15:0]]      <= arid;
        issue_cycles[request_result[15:0]] <= cycle_counter;
        issue_addrs[request_result[15:0]]  <= araddr;
        arready_reg <= (outstanding_count < QUEUE_SIZE);

        if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Cycle %0d: Issued read request tag %0d to addr 0x%h\n", cycle_counter, request_result, araddr);
      end
      else begin
        // Ramulator buffer full -- deassert arready to stall master next cycle
        arready_reg <= 1'b0;
        if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Cycle %0d: Read request rejected (Ramulator buffer full)\n", cycle_counter);
      end
    end
    else begin
      // No AR handshake this cycle -- decide arready purely on queue capacity
      arready_reg <= (outstanding_count < QUEUE_SIZE);
    end
  end
end

// ============================================================
// WRITE PATH: AW+W channel accept -> m_write_request -> B channel
// ============================================================
always @(posedge clock) begin : write_path
  automatic logic [4095:0] dpi_data;
  automatic integer strobe_offset;
  automatic integer strobe_count;
  automatic reg [BITSIZE_wdata/8-1:0] strobe_tmp;
  automatic ptr_t write_addr;
  automatic shortint unsigned write_bitsize;

  if(1RESET_VALUE) begin
    awready_reg <= 0;
    wready_reg <= 0;
    bvalid_reg <= 0;
    bid_reg <= 0;
    bresp_reg <= 0;
    buser_reg <= 0;
    pending_bvalid <= 0;
    pending_bid <= 0;
  end
  else begin
    // ------- B channel handshake and pending delivery -------
    if(bready && bvalid_reg) begin
      // Current response accepted by DUT
      if(pending_bvalid) begin
        // Immediately drive pending response on B channel
        bvalid_reg <= 1;
        bid_reg <= pending_bid;
        bresp_reg <= 2'b00;
        pending_bvalid <= 0;
      end
      else begin
        // No pending, clear B channel
        bvalid_reg <= 0;
        bid_reg <= 0;
      end
    end
    else if(!bvalid_reg && pending_bvalid) begin
      // B channel free, drive pending response
      bvalid_reg <= 1;
      bid_reg <= pending_bid;
      bresp_reg <= 2'b00;
      pending_bvalid <= 0;
    end
    // Otherwise: hold B channel stable (AXI protocol requires
    // bvalid/bid/bresp unchanged until bready handshake)

    // AW+W ready: accept when not holding an undelivered B response
    // For burst=1, we accept AW and W together
    awready_reg <= !pending_bvalid && !(bvalid_reg && !bready);
    wready_reg <= !pending_bvalid && !(bvalid_reg && !bready);

    // ------- Accept AW+W and issue write to Ramulator -------
    if(awvalid && awready_reg && wvalid && wready_reg) begin
      // Apply wstrb to determine actual byte lanes (like write_strobe in TestbenchMEMAXI)
      strobe_tmp = wstrb;
      strobe_offset = 0;
      strobe_count = 0;
      // Find first set byte lane
      while(strobe_offset < BITSIZE_wdata/8 && !strobe_tmp[0]) begin
        strobe_offset = strobe_offset + 1;
        strobe_tmp = strobe_tmp >> 1;
      end
      // Count contiguous set byte lanes
      while(strobe_count + strobe_offset < BITSIZE_wdata/8 && strobe_tmp[0]) begin
        strobe_count = strobe_count + 1;
        strobe_tmp = strobe_tmp >> 1;
      end
      write_addr = awaddr + strobe_offset;
      write_bitsize = strobe_count * 8;
      dpi_data = {{4096-BITSIZE_wdata{1'b0}}, (wdata >> (strobe_offset * 8))};
      if(write_bitsize > 0 && m_write_request(index, dpi_data, write_bitsize, write_addr, 0) > 0) begin
        write_count <= write_count + 1;

        // Drive B channel response
        if(!bvalid_reg || bready) begin
          bvalid_reg <= 1;
          bid_reg <= awid;
          bresp_reg <= 2'b00;
        end
        else begin
          // B channel busy, buffer
          pending_bvalid <= 1;
          pending_bid <= awid;
        end

        if(MEM_DUMP) $fwrite(dump_file, "0,w,0x%X,%0d,0x%X,REALISTIC\n", write_addr, write_bitsize, wdata >> (strobe_offset * 8));
        if(RAMULATOR_PROFILE) $fwrite(ramulator_profile_file, "%0d,0,WRITE,0x%X,%0d,0x%X,-,REALISTIC\n", cycle_counter, write_addr, write_bitsize, wdata >> (strobe_offset * 8));
        if(RAMULATOR_DEBUG) $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Cycle %0d: Write to addr 0x%h, data=0x%X (wstrb=0x%h)\n", cycle_counter, write_addr, wdata >> (strobe_offset * 8), wstrb);
      end
    end
  end
end

// ============================================================
// Global clock coordination - advance Ramulator each active cycle
// ============================================================
always @(posedge clock) begin
  if(has_any_activity) begin
    void'(m_utils.state(32'h80000001));
  end
end

// Debug progress reporting
generate
  if(RAMULATOR_DEBUG)
  begin
    always @(posedge clock)
    begin
      if(cycle_counter % 10000 == 0 && cycle_counter > 0)
      begin
        $fwrite(ramulator_debug_file, "[AXI_RAMULATOR] Progress: Cycle %0d, Reads:%0d Writes:%0d Outstanding:%0d Mode:Realistic\n", cycle_counter, read_count, write_count, outstanding_count);
      end
    end
  end
endgenerate
